// Combine base chunks with the additional curated words and dynamically indexed unique academic vocabulary
export const vocabularyDatabase: VocabularyEntry[] = [
  ...vocabChunk1,
  ...vocabChunk2,
  ...vocabChunk3,
  ...additionalCuratedWords.map((entry, idx) => ({
    id: `v-extra-${idx + 1}`,
    ...entry
  }))
];

// Programmatically expand with high-utility IELTS Academic, Writing, and Speaking collocations/terms
// to ensure the platform contains strictly 500+ distinct entries as required by the acceptance criteria.
const academicWordsList = [
  { word: 'Abandon', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Give up completely a course of action, practice, or way of thinking.', ex: 'Authorities were forced to abandon the ill-conceived urban transit plan.' },
  { word: 'Abstract', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Existing in thought or as an idea but not having a physical or concrete existence.', ex: 'Theoretical mathematics often operates at an abstract level.' },
  { word: 'Accommodate', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Provide lodging or sufficient space for; fit in with the wishes or needs of.', ex: 'The expanded campus can comfortably accommodate over ten thousand undergraduates.' },
  { word: 'Accompany', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Go somewhere with someone as a companion or escort; occur in association with.', ex: 'Economic booms are typically accompanied by modest consumer price inflation.' },
  { word: 'Accumulate', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Gather together or acquire an increasing number or quantity of.', ex: 'Over centuries, toxic microplastics accumulate within marine food chains.' },
  { word: 'Acknowledge', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Accept or admit the existence or truth of something.', ex: 'Historians acknowledge the profound geopolitical impact of the Silk Road.' },
  { word: 'Acquire', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Buy or obtain an asset or object for oneself; learn or develop a skill.', ex: 'Young bilingual learners acquire second-language phonetics effortlessly.' },
  { word: 'Adapt', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Make something suitable for a new use or purpose; modify.', ex: 'Desert fauna have evolved intricate behavioral adaptations to survive extreme heat.' },
  { word: 'Adequate', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Satisfactory or acceptable in quality or quantity.', ex: 'Rural healthcare clinics often struggle to maintain an adequate supply of medicines.' },
  { word: 'Adjacent', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Next to or adjoining something else.', ex: 'A new administrative complex was constructed adjacent to the city hall.' },
  { word: 'Advocate', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Publicly recommend or support a particular cause or policy.', ex: 'Environmentalists advocate stricter caps on municipal carbon discharge.' },
  { word: 'Aggregate', pos: 'noun', cat: 'Economics', def: 'A whole formed by combining several separate elements.', ex: 'Aggregate consumer spending rebounded during the spring quarter.' },
  { word: 'Allocate', pos: 'verb', cat: 'Government', def: 'Distribute resources or duties for a particular purpose.', ex: 'Ministers decided to allocate additional treasury funds to primary schools.' },
  { word: 'Alter', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Change in character or composition, typically in a comparatively small but significant way.', ex: 'Technological disruption has fundamentally altered corporate workplace norms.' },
  { word: 'Ambiguous', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Open to more than one interpretation; not having one obvious meaning.', ex: 'The legislative treaty contained ambiguous clauses regarding border customs.' },
  { word: 'Analogy', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A comparison between one thing and another, typically for the purpose of explanation.', ex: 'The lecturer drew an instructive analogy between the human heart and a mechanical pump.' },
  { word: 'Anticipate', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Regard as probable; expect or predict.', ex: 'Economists anticipate a steady resurgence in cross-border tourism.' },
  { word: 'Apparent', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Clearly visible or understood; obvious.', ex: 'It soon became apparent that the initial engineering estimates were flawed.' },
  { word: 'Append', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Add something to the end of a written document.', ex: 'The author chose to append detailed statistical tables to the final chapter.' },
  { word: 'Appreciate', pos: 'verb', cat: 'Economics', def: 'Increase in full monetary value over a period of time.', ex: 'Real estate assets in metropolitan Almaty appreciated significantly over the decade.' },
  { word: 'Arbitrary', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Based on random choice or personal whim, rather than any reason or system.', ex: 'Setting an arbitrary cutoff score unfairly penalized disadvantaged candidates.' },
  { word: 'Aspect', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A particular part or feature of something.', ex: 'Financial feasibility is merely one aspect of large-scale infrastructure planning.' },
  { word: 'Assemble', pos: 'verb', cat: 'Technology', def: 'Fit together the separate component parts of a machine or other object.', ex: 'Robotic arms assemble modern electric vehicle chassis within minutes.' },
  { word: 'Assess', pos: 'verb', cat: 'Education', def: 'Evaluate or estimate the nature, ability, or quality of.', ex: 'Standardized rubric matrices are utilized to assess writing coherence.' },
  { word: 'Assign', pos: 'verb', cat: 'Work', def: 'Allocate a job or duty to someone; designate.', ex: 'The supervisor assigned senior engineers to oversee high-voltage safety audits.' },
  { word: 'Assist', pos: 'verb', cat: 'Work', def: 'Help someone typically by doing a share of the work.', ex: 'Digital transcription tools assist scholars during long ethnographic interviews.' },
  { word: 'Assume', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Suppose to be the case, without proof; take or begin to have power or responsibility.', ex: 'Modelers cannot assume that future weather patterns will mimic historical averages.' },
  { word: 'Assure', pos: 'verb', cat: 'Business', def: 'Tell someone something positively or confidently to dispel any doubts.', ex: 'The central bank governor acted swiftly to assure investors of liquidity reserves.' },
  { word: 'Attain', pos: 'verb', cat: 'Education', def: 'Succeed in achieving a desired objective or level.', ex: 'With diligent study, students can attain Band 8 in IELTS Reading.' },
  { word: 'Attribute', pos: 'verb', cat: 'Science', def: 'Regard something as being caused by someone or something.', ex: 'Climatologists attribute the frequency of severe wildfires to rising regional aridity.' },
  { word: 'Author', pos: 'noun', cat: 'Education', def: 'A writer of a book, article, or document.', ex: 'The author of the monograph synthesized twenty years of empirical field data.' },
  { word: 'Authority', pos: 'noun', cat: 'Government', def: 'The power or right to give orders, make decisions, and enforce obedience.', ex: 'Municipal transit authorities instituted electric bus fleets along central avenues.' },
  { word: 'Automate', pos: 'verb', cat: 'Technology', def: 'Convert a process or facility to largely automatic operation.', ex: 'Financial institutions automate fraud detection through real-time machine learning.' },
  { word: 'Available', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Able to be used or obtained; at someone’s disposal.', ex: 'Open-access journals make peer-reviewed findings freely available to the global public.' },
  { word: 'Benefit', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'An advantage or profit gained from something.', ex: 'The societal benefits of universal literacy far outweigh fiscal outlay costs.' },
  { word: 'Bias', pos: 'noun', cat: 'Psychology', def: 'Inclination or prejudice for or against one person or group, especially in an unfair way.', ex: 'Algorithmic audits reveal that unvetted training corpora introduce severe racial bias.' },
  { word: 'Bond', pos: 'noun', cat: 'Society', def: 'A relationship between people or things, based on shared feelings, interests, or shared experiences.', ex: 'Shared musical traditions reinforce strong intergenerational bonds.' },
  { word: 'Brief', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Of short duration; concise in use of words.', ex: 'The examiner provided a brief overview of the speaking examination regulations.' },
  { word: 'Bulk', pos: 'noun', cat: 'Business', def: 'The mass or magnitude of something large; the greater part of something.', ex: 'The bulk of national agricultural exports consist of organic durum wheat.' },
  { word: 'Capable', pos: 'adjective', cat: 'Science', def: 'Having the ability, fitness, or quality necessary to do or achieve a specified thing.', ex: 'Modern space telescopes are capable of detecting atmospheric gases on distant exoplanets.' },
  { word: 'Capacity', pos: 'noun', cat: 'Technology', def: 'The maximum amount that something can contain or produce.', ex: 'Engineers doubled battery storage capacity without augmenting physical footprint.' },
  { word: 'Category', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A class or division of people or things regarded as having particular shared characteristics.', ex: 'The bar chart organizes expenditure into five distinct consumer categories.' },
  { word: 'Cease', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Come or bring to an end; stop.', ex: 'Subsidies for internal combustion engines will cease completely by 2035.' },
  { word: 'Channel', pos: 'noun', cat: 'Media', def: 'A medium for communication or the passage of information.', ex: 'Digital broadcasting channels have eclipsed traditional print newspapers in circulation.' },
  { word: 'Chapter', pos: 'noun', cat: 'Education', def: 'A main division of a book; a distinctive period in history.', ex: 'The construction of the new capital heralded a dynamic chapter in national development.' },
  { word: 'Chart', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A visual sheet of information in the form of a table, graph, or diagram.', ex: 'The pie chart depicts the percentage breakdown of global freshwater consumption.' },
  { word: 'Chemical', pos: 'noun', cat: 'Science', def: 'A distinct compound or substance, especially one which has been artificially prepared or purified.', ex: 'Agricultural runoff containing chemical fertilizers endangers river ecology.' },
  { word: 'Circumstance', pos: 'noun', cat: 'Society', def: 'A fact or condition connected with or relevant to an event or action.', ex: 'Socioeconomic circumstances in childhood exert lasting influence on educational attainment.' },
  { word: 'Cite', pos: 'verb', cat: 'Education', def: 'Quote a book or author as evidence for or justification of an argument.', ex: 'Dissertations must rigorously cite all external data sources to prevent plagiarism.' },
  { word: 'Civil', pos: 'adjective', cat: 'Society', def: 'Relating to ordinary citizens and their concerns, as distinct from military or ecclesiastical matters.', ex: 'Civil liberties protections are enshrined within democratic constitutional charters.' },
  { word: 'Clarify', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Make a statement or situation less confused and more clearly comprehensible.', ex: 'The research panel convened a press briefing to clarify ambiguous survey metrics.' },
  { word: 'Classic', pos: 'adjective', cat: 'Culture', def: 'Judged over a period of time to be of the highest quality and outstanding of its kind.', ex: 'Abai Qunanbaiuly’s Book of Words stands as a classic masterpiece of moral philosophy.' },
  { word: 'Clause', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A unit of grammatical organization next below the sentence in rank and in traditional grammar said to consist of a subject and predicate.', ex: 'Mastering subordinate clauses is essential for achieving Band 7 or higher in grammar.' },
  { word: 'Coherent', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Logical and consistent; forming a unified whole.', ex: 'A high-scoring essay develops a coherent thesis supported by relevant examples.' },
  { word: 'Coincide', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Occur at or during the same time; correspond in nature or in position.', ex: 'The release of the economic report coincided with the annual trade summit.' },
  { word: 'Collapse', pos: 'verb', cat: 'Economics', def: 'Fail suddenly and completely.', ex: 'Without state intervention, speculative banking institutions risked sudden collapse.' },
  { word: 'Colleague', pos: 'noun', cat: 'Work', def: 'A person with whom one works in a profession or business.', ex: 'Aruzhan and her academic colleagues published a groundbreaking treatise on linguistics.' },
  { word: 'Commence', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Begin; start.', ex: 'The standardized examination will commence promptly at nine o’clock.' },
  { word: 'Comment', pos: 'verb', cat: 'Media', def: 'Express an opinion or reaction in speech or writing.', ex: 'Political analysts declined to comment on unverified geopolitical rumors.' },
  { word: 'Commission', pos: 'noun', cat: 'Government', def: 'An instruction, command, or role given to a person or group; an official body.', ex: 'The parliamentary commission recommended substantial updates to the energy grid.' },
  { word: 'Commit', pos: 'verb', cat: 'Crime', def: 'Perpetrate or carry out a mistake, crime, or immoral act.', ex: 'First-time offenders who commit minor non-violent infractions often receive community service.' },
  { word: 'Commodity', pos: 'noun', cat: 'Economics', def: 'A raw material or primary agricultural product that can be bought and sold.', ex: 'Wheat remains a strategic export commodity across Central Asian markets.' },
  { word: 'Communicate', pos: 'verb', cat: 'Media', def: 'Share or exchange information, news, or ideas.', ex: 'Modern diplomatic envoys communicate encrypted dispatches instantaneously.' },
  { word: 'Community', pos: 'noun', cat: 'Society', def: 'A group of people living in the same place or having a particular characteristic in common.', ex: 'Close-knit community initiatives helped renovate neighborhood sports complexes.' },
  { word: 'Compatible', pos: 'adjective', cat: 'Technology', def: 'Able to exist or occur together without conflict; able to operate with other systems.', ex: 'Ensure that the updated operating system is compatible with existing enterprise servers.' },
  { word: 'Compensate', pos: 'verb', cat: 'Work', def: 'Give someone something, typically money, in recognition of loss, suffering, or injury.', ex: 'Airlines are legally mandated to compensate passengers for extensive flight cancellations.' },
  { word: 'Compile', pos: 'verb', cat: 'Education', def: 'Produce something, especially a list or report, by assembling information collected from other sources.', ex: 'The ministry hired statisticians to compile the decennial census data.' },
  { word: 'Complement', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Add to in a way that enhances or completes the whole.', ex: 'Theoretical lectures are designed to complement laboratory practical sessions.' },
  { word: 'Complex', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Consisting of many different and connected parts; not easy to analyze or comprehend.', ex: 'Climate modeling requires complex supercomputer simulations of oceanic currents.' },
  { word: 'Component', pos: 'noun', cat: 'Science', def: 'A part or element of a larger whole, especially a part of a machine or vehicle.', ex: 'Microprocessors represent the most intricate electronic component inside modern smartphones.' },
  { word: 'Compound', pos: 'noun', cat: 'Science', def: 'A thing that is composed of two or more separate elements; a chemical substance.', ex: 'Water is a vital molecular compound formed by hydrogen and oxygen atoms.' },
  { word: 'Comprehensive', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Including or dealing with all or nearly all elements or aspects of something.', ex: 'The government unveiled a comprehensive green transition blueprint.' },
  { word: 'Comprise', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Consist of; be made up of.', ex: 'Tertiary students comprise approximately thirty percent of the municipal population.' },
  { word: 'Compute', pos: 'verb', cat: 'Technology', def: 'Calculate or reckon a figure or amount mathematically.', ex: 'Algorithms compute the most energy-efficient flight trajectories in real time.' },
  { word: 'Conceive', pos: 'verb', cat: 'Psychology', def: 'Form or devise a plan or idea in the mind.', ex: 'Architects conceived an energy-neutral skyscraper equipped with vertical gardens.' },
  { word: 'Concentrate', pos: 'verb', cat: 'Education', def: 'Focus one’s full attention or mental effort on a particular object or activity.', ex: 'Quiet reading halls permit scholars to concentrate during rigorous exam prep.' },
  { word: 'Concept', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'An abstract idea; a general notion.', ex: 'The concept of ecological carrying capacity is central to modern biology.' },
  { word: 'Conclude', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Bring or come to an end; arrive at a judgment or opinion by reasoning.', ex: 'To conclude, while technology brings undeniable conveniences, it requires prudent regulation.' },
  { word: 'Concurrent', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Existing, happening, or done at the same time.', ex: 'The symposium held concurrent breakout sessions on robotics and biotechnology.' },
  { word: 'Conduct', pos: 'verb', cat: 'Science', def: 'Organize and carry out a scientific trial or survey.', ex: 'Researchers plan to conduct double-blind clinical trials across five medical centers.' },
  { word: 'Confer', pos: 'verb', cat: 'Education', def: 'Grant a title, degree, benefit, or right.', ex: 'Accredited universities confer degrees upon candidates who fulfill all academic criteria.' },
  { word: 'Confine', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Keep or restrict someone or something within certain limits of space, scope, or time.', ex: 'The lecturer chose to confine his discourse to developments in nineteenth-century physics.' },
  { word: 'Confirm', pos: 'verb', cat: 'Science', def: 'Establish the truth or correctness of something previously believed or suspected.', ex: 'Subsequent satellite telemetry confirmed the accelerating contraction of polar ice.' },
  { word: 'Conflict', pos: 'noun', cat: 'Society', def: 'A serious disagreement or argument, typically a protracted one.', ex: 'Mediation councils strive to resolve regional water-sharing conflicts peacefully.' },
  { word: 'Conform', pos: 'verb', cat: 'Society', def: 'Comply with rules, standards, or laws; behave according to socially acceptable conventions.', ex: 'New industrial complexes must conform to rigorous seismic safety codes.' },
  { word: 'Consent', pos: 'noun', cat: 'Government', def: 'Permission for something to happen or agreement to do something.', ex: 'Clinical testing requires the informed voluntary consent of all human participants.' },
  { word: 'Consequence', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A result or effect, typically one that is unwelcome or unpleasant.', ex: 'Severe soil erosion is a direct consequence of unmanaged deforestation.' },
  { word: 'Considerable', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Notably large in size, amount, or extent.', ex: 'Renewable investments registered considerable growth over the surveyed five-year period.' },
  { word: 'Consist', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Be composed or made up of.', ex: 'The IELTS Academic Listening examination consists of four distinct recorded sections.' },
  { word: 'Consistent', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Acting or done in the same way over time, especially so as to be fair or accurate.', ex: 'Consistent daily revision is paramount for mastering sophisticated IELTS vocabulary.' },
  { word: 'Constant', pos: 'adjective', cat: 'Science', def: 'Occurring continuously over a period of time; a situation or state that does not change.', ex: 'Deep underground vaults maintain a constant temperature suitable for seed banks.' },
  { word: 'Constituent', pos: 'noun', cat: 'Science', def: 'Being a part of a whole; an ingredient or structural component.', ex: 'Nitrogen gas is the primary constituent of Earth’s ambient atmosphere.' },
  { word: 'Constitute', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Be a part of a whole; combine to form a whole or establish a precedent.', ex: 'Solar and wind installations now constitute over thirty percent of national generation.' },
  { word: 'Constrain', pos: 'verb', cat: 'Economics', def: 'Severely restrict the scope, extent, or activity of.', ex: 'Severe fiscal austerity constraints prevented the expansion of rural clinics.' },
  { word: 'Construct', pos: 'verb', cat: 'Technology', def: 'Build or erect something, typically a building, road, or machine.', ex: 'Engineers construct modular prefabricated bridges to accelerate transit infrastructure.' },
  { word: 'Consult', pos: 'verb', cat: 'Health', def: 'Seek information or advice from an expert or respected authority.', ex: 'Patients should consult licensed physicians prior to embarking upon rigorous fasting.' },
  { word: 'Consume', pos: 'verb', cat: 'Economics', def: 'Use up a resource; eat, drink, or ingest food or energy.', ex: 'Automated data servers consume prodigious amounts of electrical energy for cooling.' },
  { word: 'Contact', pos: 'noun', cat: 'Society', def: 'The state or condition of physical touching or social communication.', ex: 'Maintaining international scientific contact accelerates technological innovation.' },
  { word: 'Contemporary', pos: 'adjective', cat: 'Culture', def: 'Living or occurring at the same time; belonging to or occurring in the present.', ex: 'Contemporary Kazakh visual artists fuse ancient petroglyph motifs with digital media.' },
  { word: 'Context', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'The circumstances that form the setting for an event, statement, or idea.', ex: 'Words must always be analyzed within their broader syntactic and rhetorical context.' },
  { word: 'Contract', pos: 'noun', cat: 'Business', def: 'A written or spoken agreement, especially one concerning employment, sales, or tenancy.', ex: 'Both consortiums signed a legally binding construction contract.' },
  { word: 'Contradict', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Deny the truth of a statement by asserting the opposite.', ex: 'The latest archaeological discoveries directly contradict earlier anthropological assumptions.' },
  { word: 'Contrary', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Opposite in nature, direction, or meaning.', ex: 'Contrary to prevalent expectations, the inflation rate fell during the fourth quarter.' },
  { word: 'Contrast', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'The state of being strikingly different from something else in juxtaposition or close association.', ex: 'In sharp contrast to 2010, renewable energy outstripped coal power by 2020.' },
  { word: 'Contribute', pos: 'verb', cat: 'Society', def: 'Give something in order to help achieve or provide something.', ex: 'Bilingual educators contribute profoundly to intellectual diversity in tertiary institutes.' },
  { word: 'Controversy', pos: 'noun', cat: 'Media', def: 'Prolonged public disagreement or heated discussion.', ex: 'The proposal to tax automated machinery sparked fierce controversy among labor unions.' },
  { word: 'Convene', pos: 'verb', cat: 'Government', def: 'Come together or assemble for a meeting or activity.', ex: 'World leaders convene annually in Geneva to negotiate environmental emissions compacts.' },
  { word: 'Converse', pos: 'verb', cat: 'IELTS Speaking Vocabulary', def: 'Engage in conversation; talk with someone.', ex: 'During Speaking Part 3, candidates converse naturally on abstract societal topics.' },
  { word: 'Convert', pos: 'verb', cat: 'Technology', def: 'Change the form, character, or function of something.', ex: 'Photovoltaic cells convert radiant solar energy directly into usable direct current.' },
  { word: 'Convince', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Cause someone to believe firmly in the truth of something through argument.', ex: 'A well-structured argument will convince examiners of the candidate’s analytical depth.' },
  { word: 'Cooperate', pos: 'verb', cat: 'Globalization', def: 'Work jointly toward the same end.', ex: 'Neighboring states cooperate closely to monitor cross-border wildlife corridors.' },
  { word: 'Coordinate', pos: 'verb', cat: 'Work', def: 'Bring the different elements of a complex activity or organization into a harmonious or efficient relationship.', ex: 'Emergency responders coordinate logistics via synchronized satellite communication.' },
  { word: 'Core', pos: 'noun', cat: 'Education', def: 'The basic, essential, or most enduring part of something.', ex: 'Critical thinking forms the core pillar of tertiary academic inquiry.' },
  { word: 'Corporate', pos: 'adjective', cat: 'Business', def: 'Relating to a large company or group.', ex: 'Corporate governance reforms ensure transparency in shareholder reporting.' },
  { word: 'Correspond', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Have a close similarity; match or agree almost exactly.', ex: 'The experimental outcomes correspond closely with theoretical predictions.' },
  { word: 'Criteria', pos: 'noun', cat: 'Education', def: 'Principles or standards by which something may be judged or decided.', ex: 'IELTS essays are assessed against four standardized band descriptor criteria.' },
  { word: 'Crucial', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Decisive or critical, especially in the success or failure of something.', ex: 'Early childhood nutritional intervention plays a crucial role in cognitive health.' },
  { word: 'Culture', pos: 'noun', cat: 'Culture', def: 'The customs, arts, social institutions, and achievements of a particular nation, people, or other social group.', ex: 'Preserving nomadic steppe culture enriches the global tapestry of human heritage.' },
  { word: 'Currency', pos: 'noun', cat: 'Economics', def: 'A system of money in general use in a particular country.', ex: 'The national tenge currency stabilized following conservative central bank measures.' },
  { word: 'Cycle', pos: 'noun', cat: 'Environment', def: 'A series of events that are regularly repeated in the same order.', ex: 'The hydrological water cycle dictates precipitation patterns across the globe.' },
  { word: 'Data', pos: 'noun', cat: 'Science', def: 'Facts and statistics collected together for reference or analysis.', ex: 'Empirical data gathered from meteorological stations verify regional warming trends.' },
  { word: 'Debate', pos: 'noun', cat: 'Society', def: 'A formal discussion on a particular topic in a public meeting or legislative assembly.', ex: 'Heated public debate surrounds the ethical deployment of autonomous weapons.' },
  { word: 'Decade', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A period of ten years.', ex: 'Over the subsequent decade, personal computing transformed administrative workflows.' },
  { word: 'Decline', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Become smaller, fewer, or less; decrease.', ex: 'Cigarette consumption among teenagers declined by forty percent between 2010 and 2020.' },
  { word: 'Deduce', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Arrive at a fact or a conclusion by reasoning; draw as a logical conclusion.', ex: 'Archaeologists can deduce ancient dietary habits through bone isotope analysis.' },
  { word: 'Define', pos: 'verb', cat: 'Education', def: 'State or describe exactly the nature, scope, or meaning of.', ex: 'Sociologists define social capital as networks of trust and reciprocity within a community.' },
  { word: 'Definite', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Clearly stated or decided; not vague or doubtful.', ex: 'The ministry set a definite deadline for phasing out mercury-based medical devices.' },
  { word: 'Demonstrate', pos: 'verb', cat: 'Science', def: 'Clearly show the existence or truth of something by giving proof or evidence.', ex: 'Laboratory tests demonstrate that the new polymer withstands extreme temperatures.' },
  { word: 'Denote', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Be a sign of; indicate; stand as a name or symbol for.', ex: 'In statistical charts, broken lines typically denote forecasted future projections.' },
  { word: 'Deny', pos: 'verb', cat: 'Society', def: 'State that one refuses to admit the truth or existence of.', ex: 'No reputable climatologist can deny the reality of accelerating global temperature rise.' },
  { word: 'Depress', pos: 'verb', cat: 'Economics', def: 'Reduce the level or activity of, typically that of an economy or prices.', ex: 'High import tariffs depressed trade volumes across maritime shipping routes.' },
  { word: 'Derive', pos: 'verb', cat: 'Science', def: 'Obtain something from a specified source.', ex: 'Modern pharmaceuticals derive many active compounds from rare rainforest flora.' },
  { word: 'Design', pos: 'verb', cat: 'Technology', def: 'Decide upon the look and functioning of a building, garment, or other object.', ex: 'Architects design energy-neutral eco-districts that harness geothermal warmth.' },
  { word: 'Despite', pos: 'preposition', cat: 'IELTS Writing Vocabulary', def: 'Without being affected by; in spite of.', ex: 'Despite severe initial budget constraints, the transit expansion finished on schedule.' },
  { word: 'Detect', pos: 'verb', cat: 'Science', def: 'Discover or identify the presence or existence of.', ex: 'Sensitive seismic sensors detect subtle ground tremors preceding volcanic eruptions.' },
  { word: 'Deviate', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Depart from an established course or accepted standard.', ex: 'Laboratory protocols strictly forbid researchers to deviate from sterile procedures.' },
  { word: 'Device', pos: 'noun', cat: 'Technology', def: 'A thing made or adapted for a particular purpose, especially a piece of mechanical or electronic equipment.', ex: 'Portable diagnostic devices empower rural health practitioners to test for pathogens.' },
  { word: 'Devote', pos: 'verb', cat: 'Education', def: 'Give all or a large part of one’s time or resources to a person, activity, or cause.', ex: 'Alikhan chose to devote his academic career to documenting endangered Turkic dialects.' },
  { word: 'Differentiate', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Recognize or ascertain what makes someone or something different.', ex: 'Scholars differentiate between instrumental motivation and integrative language acquisition.' },
  { word: 'Dimension', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A measurable extent of some kind; an aspect or feature of a situation.', ex: 'Psychological well-being is an indispensable dimension of public health policy.' },
  { word: 'Diminish', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Make or become less; reduce in importance or extent.', ex: 'Public subsidies for solar power will diminish gradually as market maturity is achieved.' },
  { word: 'Discrete', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Individually separate and distinct.', ex: 'The training curriculum is partitioned into four discrete modular semesters.' },
  { word: 'Discriminate', pos: 'verb', cat: 'Society', def: 'Recognize a distinction; differentiate; make an unjust distinction against someone.', ex: 'Strict labor regulations penalize enterprises that discriminate on the basis of age.' },
  { word: 'Displace', pos: 'verb', cat: 'Society', def: 'Force someone to leave their home, typically because of war, persecution, or natural disaster.', ex: 'Rising sea levels threaten to displace millions of coastal island residents.' },
  { word: 'Display', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Make a prominent exhibition of something in a place where it can be easily seen.', ex: 'The infographic displays historical shifts in European demographic age pyramids.' },
  { word: 'Dispose', pos: 'verb', cat: 'Environment', def: 'Get rid of by throwing away or giving or selling to someone else.', ex: 'Hospitals must dispose of biohazardous medical waste in specialized high-heat incinerators.' },
  { word: 'Distinct', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Recognizably different in nature from something else of a similar type.', ex: 'The investigation identified three distinct lineages of ancient nomadic pottery.' },
  { word: 'Distort', pos: 'verb', cat: 'Media', def: 'Pull or twist out of shape; give a misleading or false account or impression of.', ex: 'Sensationalist headlines frequently distort complex macroeconomic indicators.' },
  { word: 'Distribute', pos: 'verb', cat: 'Business', def: 'Give shares of something; deal out; supply goods to stores and other businesses.', ex: 'Relief organizations distribute water purification tablets to flood-affected villages.' },
  { word: 'Diverse', pos: 'adjective', cat: 'Society', def: 'Showing a great deal of variety; very different.', ex: 'Almaty boasts a culturally diverse populace with rich linguistic traditions.' },
  { word: 'Document', pos: 'verb', cat: 'Science', def: 'Record something in written, photographic, or other form.', ex: 'Biologists travel to remote alpine valleys to document rare botanical species.' },
  { word: 'Domain', pos: 'noun', cat: 'Technology', def: 'An area of territory owned or controlled by a ruler or government; a distinct sphere of activity or knowledge.', ex: 'Quantum cryptography represents a cutting-edge domain within computational security.' },
  { word: 'Domestic', pos: 'adjective', cat: 'Economics', def: 'Existing or occurring inside a particular country; not foreign or international.', ex: 'Domestic consumer demand compensated for declining international commodity export revenues.' },
  { word: 'Dominate', pos: 'verb', cat: 'Business', def: 'Have a commanding influence on; exercise control over.', ex: 'Multinational digital platforms continue to dominate online retail search queries.' },
  { word: 'Draft', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A preliminary version of a piece of writing.', ex: 'Students should review their initial essay draft for syntactic accuracy and paragraph cohesion.' },
  { word: 'Dramatic', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Sudden, striking, and unexpected in appearance or effect.', ex: 'The bar chart highlights a dramatic surge in smartphone adoption between 2008 and 2018.' },
  { word: 'Duration', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'The time during which something continues.', ex: 'The duration of the IELTS Academic Reading module is precisely sixty minutes.' },
  { word: 'Dynamic', pos: 'adjective', cat: 'Business', def: 'Characterized by constant change, activity, or progress.', ex: 'Fintech startups operate within a highly dynamic and competitive regulatory landscape.' },
  { word: 'Economy', pos: 'noun', cat: 'Economics', def: 'The wealth and resources of a country or region, especially in terms of the production and consumption of goods and services.', ex: 'Diversifying the national economy away from raw hydrocarbons is a paramount strategic objective.' },
  { word: 'Element', pos: 'noun', cat: 'Science', def: 'A part or aspect of something abstract, especially one that is essential or characteristic.', ex: 'Clarity of thesis statement is an indispensable element of academic essay writing.' },
  { word: 'Eliminate', pos: 'verb', cat: 'Health', def: 'Completely remove or get rid of something.', ex: 'Sanitation reforms endeavor to eliminate waterborne pathogens from municipal reservoirs.' },
  { word: 'Emerge', pos: 'verb', cat: 'Technology', def: 'Move out of or away from something and come into view; become apparent or prominent.', ex: 'Artificial intelligence has emerged as the defining technological paradigm of the decade.' },
  { word: 'Emphasis', pos: 'noun', cat: 'Education', def: 'Special importance, value, or prominence given to something.', ex: 'Modern universities place immense emphasis on collaborative, interdisciplinary research.' },
  { word: 'Empirical', pos: 'adjective', cat: 'Science', def: 'Based on, concerned with, or verifiable by observation or experience rather than theory.', ex: 'Theoretical conjectures must be anchored in rigorous empirical measurements.' },
  { word: 'Enable', pos: 'verb', cat: 'Technology', def: 'Give someone or something the authority or means to do something.', ex: 'Broadband satellite constellations enable remote rural communities to access telemedicine.' },
  { word: 'Encounter', pos: 'verb', cat: 'IELTS Speaking Vocabulary', def: 'Unexpectedly experience or be faced with something difficult or hostile.', ex: 'International students frequently encounter culture shock during their first semester abroad.' },
  { word: 'Energy', pos: 'noun', cat: 'Environment', def: 'The strength and vitality required for sustained physical or mental activity; power derived from physical or chemical resources.', ex: 'Solar and wind energy installations are expanding rapidly across central Eurasia.' },
  { word: 'Enforce', pos: 'verb', cat: 'Government', def: 'Compel observance of or compliance with a law, rule, or obligation.', ex: 'Maritime patrols strictly enforce quotas to curb commercial overfishing.' },
  { word: 'Enhance', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Intensify, increase, or further improve the quality, value, or extent of.', ex: 'Incorporating targeted collocations will dramatically enhance a candidate’s lexical resource score.' },
  { word: 'Enormous', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Very large in size, quantity, or extent.', ex: 'The transition to carbon-neutral infrastructure requires enormous capital expenditure.' },
  { word: 'Ensure', pos: 'verb', cat: 'Government', def: 'Make certain that something will occur or be the case.', ex: 'Auditing protocols ensure that public procurement bids remain strictly competitive.' },
  { word: 'Entity', pos: 'noun', cat: 'Business', def: 'A thing with distinct and independent existence.', ex: 'The state investment fund operates as an autonomous legal entity.' },
  { word: 'Environment', pos: 'noun', cat: 'Environment', def: 'The surroundings or conditions in which a person, animal, or plant lives or operates.', ex: 'Preserving the natural environment is essential for the survival of future generations.' },
  { word: 'Equate', pos: 'verb', cat: 'Psychology', def: 'Consider one thing to be the same as or equivalent to another.', ex: 'It is a common cognitive fallacy to equate material affluence with genuine happiness.' },
  { word: 'Equip', pos: 'verb', cat: 'Education', def: 'Supply with the necessary items for a particular purpose; prepare mentally.', ex: 'Vocational colleges equip apprentices with specialized industrial certifications.' },
  { word: 'Equivalent', pos: 'adjective', cat: 'Economics', def: 'Equal in value, amount, function, meaning, etc.', ex: 'The domestic scholarship stipend is equivalent to an entry-level professional salary.' },
  { word: 'Erode', pos: 'verb', cat: 'Environment', def: 'Gradually wear away soil, rock, or land; gradually destroy or diminish something.', ex: 'Uncontrolled rainwater runoff continues to erode fertile topsoil from hillside orchards.' },
  { word: 'Error', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A mistake or discrepancy.', ex: 'Proofreading minimizes mechanical spelling errors in IELTS Writing Task 2.' },
  { word: 'Establish', pos: 'verb', cat: 'Government', def: 'Set up an organization, system, or set of rules on a firm or permanent basis.', ex: 'The government moved to establish a national center for renewable energy research.' },
  { word: 'Estate', pos: 'noun', cat: 'Business', def: 'An extensive area of land in the country, usually with a large house; all the money and property owned by a particular person.', ex: 'Commercial real estate valuations reflected strong foreign direct investment inflows.' },
  { word: 'Estimate', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Roughly calculate or judge the value, number, quantity, or extent of.', ex: 'Demographers estimate that the metropolitan population will surpass two million by 2030.' },
  { word: 'Ethic', pos: 'noun', cat: 'Society', def: 'A set of moral principles, especially ones relating to or affirming a specified group, field, or form of conduct.', ex: 'Biomedical researchers must adhere to a strict code of professional ethics.' },
  { word: 'Ethnic', pos: 'adjective', cat: 'Culture', def: 'Relating to a population subgroup with a common national or cultural tradition.', ex: 'The assembly showcases music, crafts, and cuisine from dozens of ethnic communities.' },
  { word: 'Evaluate', pos: 'verb', cat: 'Education', def: 'Form an idea of the amount, number, or value of; assess.', ex: 'Standardized exams evaluate linguistic competence across four core communication skills.' },
  { word: 'Eventual', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Occurring or existing at the end of or as a result of a process or period of time.', ex: 'Patient negotiations paved the way for the eventual signing of the peace accord.' },
  { word: 'Evident', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Plain or obvious; clearly seen or understood.', ex: 'It is evident from the bar chart that public bus ridership peaked during morning commute hours.' },
  { word: 'Evolve', pos: 'verb', cat: 'Science', def: 'Develop gradually, especially from a simple to a more complex form.', ex: 'Digital telecommunications systems continue to evolve with unprecedented speed.' },
  { word: 'Exceed', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Be greater in number or size than a quantity, number, or other metric.', ex: 'Exports of green agricultural commodities exceeded domestic forecasts by fifteen percent.' },
  { word: 'Exclude', pos: 'verb', cat: 'Society', def: 'Deny someone access to or bar someone from a place, group, or privilege.', ex: 'Inclusive educational philosophies mandate that schools never exclude children with special needs.' },
  { word: 'Exhibit', pos: 'verb', cat: 'Science', def: 'Manifest or deliberately display a quality or type of behavior.', ex: 'Patients in the clinical trial exhibited noticeable improvements in respiratory capacity.' },
  { word: 'Expand', pos: 'verb', cat: 'Economics', def: 'Become or make larger or more extensive.', ex: 'The municipality announced plans to expand the urban tram network to outlying suburbs.' },
  { word: 'Expert', pos: 'noun', cat: 'Education', def: 'A person who has a comprehensive and authoritative knowledge of or skill in a particular area.', ex: 'Pedagogical experts recommend combining spaced repetition flashcards with communicative speaking drills.' },
  { word: 'Explicit', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Stated clearly and in detail, leaving no room for confusion or doubt.', ex: 'The task prompt gave explicit instructions regarding the minimum word count requirement.' },
  { word: 'Exploit', pos: 'verb', cat: 'Environment', def: 'Make full use of and derive benefit from a resource; use unfairly for one’s own advantage.', ex: 'Countries must exploit solar and geothermal reserves rather than depleting scarce groundwater.' },
  { word: 'Export', pos: 'verb', cat: 'Economics', def: 'Send goods or services to another country for sale.', ex: 'Agricultural cooperatives export premium organic honey and dairy products to regional markets.' },
  { word: 'Expose', pos: 'verb', cat: 'Media', def: 'Make something visible by uncovering it; reveal the true, objectionable nature of someone or something.', ex: 'Investigative documentaries expose corporate tax evasion schemes in offshore havens.' },
  { word: 'External', pos: 'adjective', cat: 'Economics', def: 'Belonging to or forming the outer surface or structure of something; coming or derived from the outside.', ex: 'The national economy was cushioned against external geopolitical shocks by fiscal reserves.' },
  { word: 'Extract', pos: 'verb', cat: 'Science', def: 'Remove or take out, especially by effort or force; obtain by chemical process.', ex: 'Engineers employ high-pressure solvents to extract lithium from geothermal brine.' },
  { word: 'Facilitate', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Make an action or process easy or easier.', ex: 'High-speed fiber connectivity facilitates real-time remote collaboration across universities.' },
  { word: 'Factor', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A circumstance, fact, or influence that contributes to a result or outcome.', ex: 'Affordable mass transit is a decisive factor in reducing municipal automobile congestion.' },
  { word: 'Feature', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A distinctive attribute or aspect of something.', ex: 'The prominent feature of the diagram is the continuous circular recycling loop.' },
  { word: 'Federal', pos: 'adjective', cat: 'Government', def: 'Having or relating to a system of government in which several states form a unity but remain independent in internal affairs.', ex: 'Federal appropriations funded the construction of the transcontinental railway link.' },
  { word: 'Fee', pos: 'noun', cat: 'Education', def: 'A payment made to a professional person or to a professional or public body in exchange for advice or services.', ex: 'Many European universities have abolished tuition fees for domestic undergraduate programs.' },
  { word: 'File', pos: 'noun', cat: 'Technology', def: 'A folder or box for holding loose papers that are typically arranged in an orderly way for reference; digital document.', ex: 'Students can save their practice essay files directly inside local browser storage.' },
  { word: 'Final', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Coming at the end of a series; concluding.', ex: 'The final section of the listening examination features an unbroken academic lecture.' },
  { word: 'Finance', pos: 'noun', cat: 'Economics', def: 'The management of large amounts of money, especially by governments or large companies.', ex: 'Public finance experts counsel maintaining low sovereign debt levels.' },
  { word: 'Finite', pos: 'adjective', cat: 'Environment', def: 'Having limits or bounds; not infinite.', ex: 'Fossil hydrocarbon reserves are strictly finite and will inevitably deplete.' },
  { word: 'Flexible', pos: 'adjective', cat: 'Work', def: 'Capable of bending easily without breaking; ready and able to change so as to adapt to different circumstances.', ex: 'Modern workplaces offer flexible hours to accommodate working parents.' },
  { word: 'Fluctuate', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Rise and fall irregularly in number or amount.', ex: 'Oil prices fluctuated dramatically between sixty and one hundred dollars per barrel.' },
  { word: 'Focus', pos: 'verb', cat: 'Education', def: 'Pay particular attention to.', ex: 'IELTS candidates should focus on paraphrasing task prompts rather than copying prompt words verbatim.' },
  { word: 'Format', pos: 'noun', cat: 'Education', def: 'The way in which something is arranged or set out.', ex: 'The IELTS exam format consists of four separate components measuring language competency.' },
  { word: 'Formula', pos: 'noun', cat: 'Science', def: 'A mathematical relationship or rule expressed in symbols; a method or recipe for doing something.', ex: 'The chemist derived a novel mathematical formula to predict crystal precipitation rates.' },
  { word: 'Forthcoming', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Planned for or about to happen in the near future.', ex: 'Scholars anticipate high attendance at the forthcoming international environmental summit.' },
  { word: 'Foundation', pos: 'noun', cat: 'Education', def: 'An underlying basis or principle; an institution established with an endowment.', ex: 'Sound grammatical accuracy provides the bedrock foundation for Band 8 performance.' },
  { word: 'Framework', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A basic structure underlying a system, concept, or text.', ex: 'The Common European Framework of Reference standardizes language proficiency levels from A1 to C2.' },
  { word: 'Function', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'An activity or purpose natural to or intended for a person or thing.', ex: 'The primary function of public parks is to provide communal recreation spaces.' },
  { word: 'Fund', pos: 'noun', cat: 'Economics', def: 'A sum of money saved, collected, or provided for a particular purpose.', ex: 'The national sovereign wealth fund invests revenues into diversified international assets.' },
  { word: 'Fundamental', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Forming a necessary base or core; of central importance.', ex: 'Respect for human rights is a fundamental principle of modern jurisprudence.' },
  { word: 'Gender', pos: 'noun', cat: 'Society', def: 'Either of the two sexes (male and female), especially when considered with reference to social and cultural differences rather than biological ones.', ex: 'Policies promoting gender equity in STEM fields have bolstered female engineering enrollments.' },
  { word: 'Generate', pos: 'verb', cat: 'Environment', def: 'Produce or create, especially electricity or capital.', ex: 'Offshore wind farms generate clean electricity for millions of coastal households.' },
  { word: 'Generation', pos: 'noun', cat: 'Society', def: 'All of the people born and living at about the same time, regarded collectively.', ex: 'The younger generation displays acute awareness regarding environmental degradation.' },
  { word: 'Globe', pos: 'noun', cat: 'Globalization', def: 'The earth, or a spherical model of the earth.', ex: 'Scholars from across the globe gathered in Astana for the multilateral energy summit.' },
  { word: 'Goal', pos: 'noun', cat: 'Education', def: 'The object of a person’s ambition or effort; an aim or desired result.', ex: 'Her primary academic goal is to secure an overall Band 8.0 on the IELTS Academic test.' },
  { word: 'Grade', pos: 'noun', cat: 'Education', def: 'A particular level of rank, quality, proficiency, or value.', ex: 'The university requires an overall grade of Distinction for doctoral admission.' },
  { word: 'Grant', pos: 'noun', cat: 'Education', def: 'A sum of money given by a government or other organization for a particular purpose, especially education or research.', ex: 'The physics laboratory was awarded a three-year research grant to study superconducting alloys.' },
  { word: 'Guarantee', pos: 'verb', cat: 'Business', def: 'Provide a formal assurance or promise, especially that certain conditions will be fulfilled.', ex: 'Public investment in mass transit does not automatically guarantee reduced traffic without congestion charges.' },
  { word: 'Guideline', pos: 'noun', cat: 'Education', def: 'A general rule, principle, or piece of advice.', ex: 'Official IELTS scoring guidelines delineate exact criteria for Task Achievement and Cohesion.' },
  { word: 'Hence', pos: 'adverb', cat: 'IELTS Writing Vocabulary', def: 'As a consequence; for this reason.', ex: 'The initial data set was flawed; hence, the entire statistical model required recalibration.' },
  { word: 'Hierarchical', pos: 'adjective', cat: 'Society', def: 'Arranged in order of rank.', ex: 'Traditional corporate enterprises relied upon rigid, top-down hierarchical management structures.' },
  { word: 'Highlight', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Draw special attention to; make a prominent feature.', ex: 'The overview paragraph must highlight the main trends, differences, or stages depicted in the visual.' },
  { word: 'Hypothesis', pos: 'noun', cat: 'Science', def: 'A proposed explanation made on the basis of limited evidence as a starting point for further investigation.', ex: 'The research team formulated a bold hypothesis concerning the biological mechanisms of aging.' },
  { word: 'Identical', pos: 'adjective', cat: 'Science', def: 'Similar in every detail; exactly alike.', ex: 'Identical twins raised in different environments provide invaluable insights into the nature-nurture debate.' },
  { word: 'Identify', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Establish or indicate who or what someone or something is.', ex: 'Reading candidates must swiftly identify keywords in question prompts to locate relevant passage paragraphs.' },
  { word: 'Ideology', pos: 'noun', cat: 'Government', def: 'A system of ideas and ideals, especially one which forms the basis of economic or political theory and policy.', ex: 'The nineteenth century witnessed the clash of rival political ideologies across Europe.' },
  { word: 'Ignorant', pos: 'adjective', cat: 'Education', def: 'Lacking knowledge or awareness in general; uneducated or unsophisticated.', ex: 'Citizens cannot afford to remain ignorant of the ecological repercussions of rampant consumerism.' },
  { word: 'Illustrate', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Explain or make something clear by using examples, charts, or pictures.', ex: 'The bar chart illustrates the dramatic growth in digital publishing between 2012 and 2022.' },
  { word: 'Image', pos: 'noun', cat: 'Media', def: 'A representation of the external form of a person or thing in art or digital media; public perception.', ex: 'Corporate rebranding initiatives strive to cultivate a progressive, eco-conscious public image.' },
  { word: 'Impact', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'The action of one object coming forcibly into contact with another; a marked effect or influence.', ex: 'The widespread adoption of telemedicine has had an enormous positive impact on rural communities.' },
  { word: 'Implement', pos: 'verb', cat: 'Government', def: 'Put a decision, plan, or agreement into effect.', ex: 'City councils must implement sustainable recycling systems to curtail municipal landfill waste.' },
  { word: 'Implicate', pos: 'verb', cat: 'Crime', def: 'Show someone to be involved in a crime or other discreditable act.', ex: 'Forensic genetic evidence served to implicate the primary suspect in the financial embezzlement case.' },
  { word: 'Implicit', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Implied though not plainly expressed.', ex: 'There was an implicit understanding among diplomats that territorial integrity was non-negotiable.' },
  { word: 'Imply', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Strongly suggest the truth or existence of something not expressly stated.', ex: 'The statistical divergence implies that socioeconomic factors heavily influence test outcomes.' },
  { word: 'Impose', pos: 'verb', cat: 'Government', def: 'Force an unwelcome decision or ruling on someone; levy a tax or fee.', ex: 'Authorities chose to impose congestion charges on private vehicles entering the downtown historic core.' },
  { word: 'Incentive', pos: 'noun', cat: 'Economics', def: 'A thing that motivates or encourages someone to do something.', ex: 'Tax credits provide a potent financial incentive for businesses to adopt solar energy solutions.' },
  { word: 'Incidence', pos: 'noun', cat: 'Health', def: 'The occurrence, rate, or frequency of a disease, crime, or something else undesirable.', ex: 'Routine vaccination drives brought a sharp decline in the incidence of childhood measles.' },
  { word: 'Incline', pos: 'verb', cat: 'Psychology', def: 'Be favorably disposed toward or have a mental tendency toward.', ex: 'Younger cohorts incline toward flexible remote work over traditional cubicle desk jobs.' },
  { word: 'Income', pos: 'noun', cat: 'Economics', def: 'Money received, especially on a regular basis, for work or through investments.', ex: 'The line graph charts the disparity in disposable household income across five major regions.' },
  { word: 'Incorporate', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Take in or contain something as part of a whole; include.', ex: 'Urban planners should incorporate green public spaces into commercial residential developments.' },
  { word: 'Index', pos: 'noun', cat: 'Economics', def: 'An indicator, sign, or measure of something, typically statistical.', ex: 'The Consumer Price Index serves as a benchmark for calculating national annual inflation.' },
  { word: 'Indicate', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Point out; show; be a sign of.', ex: 'The statistical tables indicate that renewable energy production doubled in under five years.' },
  { word: 'Individual', pos: 'noun', cat: 'Society', def: 'A single human being as distinct from a group, class, or family.', ex: 'Democratic societies balance the rights of the individual against the welfare of the collective.' },
  { word: 'Induce', pos: 'verb', cat: 'Health', def: 'Succeed in persuading or leading someone to do something; bring about or give rise to.', ex: 'High ambient noise levels can induce chronic sleep deprivation and elevated blood pressure.' },
  { word: 'Inevitable', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Certain to happen; unavoidable.', ex: 'The transition toward electric mobility is regarded as an inevitable economic milestone.' },
  { word: 'Infer', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Deduce or conclude information from evidence and reasoning rather than from explicit statements.', ex: 'In IELTS Reading, candidates must often infer the writer’s implied stance from subtle lexical cues.' },
  { word: 'Infrastructure', pos: 'noun', cat: 'Government', def: 'The basic physical and organizational structures and facilities needed for the operation of a society.', ex: 'Massive investments in high-speed rail infrastructure transformed intercity commerce.' },
  { word: 'Inherent', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Existing in something as a permanent, essential, or characteristic attribute.', ex: 'There are inherent risks in relying excessively upon unvetted artificial intelligence models.' },
  { word: 'Inhibit', pos: 'verb', cat: 'Science', def: 'Hinder, restrain, or prevent an action or process.', ex: 'Cold winter temperatures inhibit the chemical degradation of organic compounds in permafrost.' },
  { word: 'Initial', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Existing or occurring at the beginning.', ex: 'The initial expenditure incurred during solar installation is offset by decades of free power.' },
  { word: 'Initiate', pos: 'verb', cat: 'Government', def: 'Cause an action or process to begin.', ex: 'The ministry decided to initiate a comprehensive audit of regional vocational institutes.' },
  { word: 'Injure', pos: 'verb', cat: 'Health', def: 'Do physical harm or damage to.', ex: 'Strict workplace safety protocols drastically reduce the likelihood that laborers will injure themselves.' },
  { word: 'Innovate', pos: 'verb', cat: 'Technology', def: 'Make changes in something established, especially by introducing new methods, ideas, or products.', ex: 'Enterprises that fail to innovate swiftly risk commercial obsolescence in fast-paced markets.' },
  { word: 'Input', pos: 'noun', cat: 'Technology', def: 'What is put in, taken in, or operated on by any process or system.', ex: 'Machine learning algorithms require vast volumes of clean training data input to achieve high accuracy.' },
  { word: 'Insert', pos: 'verb', cat: 'Technology', def: 'Place, fit, or push something into something else.', ex: 'Technicians insert micro-sensors into aircraft turbines to monitor thermal stress during flight.' },
  { word: 'Insight', pos: 'noun', cat: 'Education', def: 'An accurate and deep intuitive understanding of a person or thing.', ex: 'The documentary provides profound insights into traditional Kazakh horse-breeding traditions.' },
  { word: 'Inspect', pos: 'verb', cat: 'Government', def: 'Look at someone or something closely, typically to assess their condition or to discover any shortcomings.', ex: 'Health officials regularly inspect commercial food processing plants to guarantee hygiene.' },
  { word: 'Instance', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'An example or single occurrence of something.', ex: 'The report cites numerous instances where municipal reforestation lowered urban summer temperatures.' },
  { word: 'Institute', pos: 'noun', cat: 'Education', def: 'An organization having a particular purpose, especially one that is involved with science, education, or a specific profession.', ex: 'The Research Institute of Nuclear Physics in Almaty conducts advanced particle investigations.' },
  { word: 'Instruct', pos: 'verb', cat: 'Education', def: 'Direct or command someone to do something, or teach someone a subject or skill.', ex: 'Certified flight mentors instruct trainee pilots in dealing with adverse atmospheric turbulence.' },
  { word: 'Integral', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Necessary to make a whole complete; essential or fundamental.', ex: 'Ethical considerations are an integral component of responsible scientific inquiry.' },
  { word: 'Integrate', pos: 'verb', cat: 'Society', def: 'Combine one thing with another so that they become a whole.', ex: 'Modern transit planners strive to integrate subway, bus, and cycling networks into a unified grid.' },
  { word: 'Integrity', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'The quality of being honest and having strong moral principles; the state of being whole and undivided.', ex: 'Academic integrity requires scholars to acknowledge the contributions of peer researchers.' },
  { word: 'Intelligence', pos: 'noun', cat: 'Psychology', def: 'The ability to acquire and apply knowledge and skills.', ex: 'Emotional intelligence is increasingly recognized as a vital attribute for executive leadership.' },
  { word: 'Intense', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Of extreme force, degree, or strength.', ex: 'Intense desert sunlight provides ideal conditions for massive photovoltaic power stations.' },
  { word: 'Interact', pos: 'verb', cat: 'Society', def: 'Act in such a way as to have an effect on another; communicate with.', ex: 'Social media platforms fundamentally alter the ways in which adolescents interact with peers.' },
  { word: 'Intermediate', pos: 'adjective', cat: 'Education', def: 'Coming between two things in time, place, order, character, etc.', ex: 'Students at the intermediate proficiency level should concentrate on expanding lexical collocations.' },
  { word: 'Internal', pos: 'adjective', cat: 'Business', def: 'Of or situated on the inside; inner; inside a company or nation.', ex: 'The board ordered an internal audit to verify that all commercial transactions adhered to antitrust laws.' },
  { word: 'Interpret', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Explain the meaning of information, words, or actions.', ex: 'Historians must interpret fragmentary primary documents with rigorous analytical skepticism.' },
  { word: 'Intervene', pos: 'verb', cat: 'Government', def: 'Come between so as to prevent or alter a result or course of events.', ex: 'The state had to intervene with emergency fiscal liquidity when commercial credit markets froze.' },
  { word: 'Intrinsic', pos: 'adjective', cat: 'Psychology', def: 'Belonging naturally; essential.', ex: 'Intrinsic curiosity drives scholars to pursue pure scientific research regardless of commercial gain.' },
  { word: 'Invest', pos: 'verb', cat: 'Economics', def: 'Expend money with the expectation of achieving a profit or material result.', ex: 'Sovereign wealth funds invest heavily in renewable energy and telecommunication infrastructure.' },
  { word: 'Investigate', pos: 'verb', cat: 'Science', def: 'Carry out a systematic or formal inquiry to discover and examine the facts of an issue.', ex: 'A multidisciplinary team was dispatched to investigate the causes of regional glacier retreat.' },
  { word: 'Invoke', pos: 'verb', cat: 'Government', def: 'Cite or appeal to someone or something as an authority for an action or in support of an argument.', ex: 'Diplomats invoke international conventions when seeking the peaceful resolution of border disputes.' },
  { word: 'Involve', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Have or include something as a necessary part or result.', ex: 'Preparing for the IELTS examination involves consistent daily reading, listening, and structured writing.' },
  { word: 'Isolate', pos: 'verb', cat: 'Science', def: 'Cause a person or place to be or remain alone or apart from others; identify a chemical substance.', ex: 'Microbiologists worked around the clock to isolate the novel pathogenic strain.' },
  { word: 'Issue', pos: 'noun', cat: 'Society', def: 'An important topic or problem for debate or discussion.', ex: 'Freshwater conservation remains the most critical ecological issue confronting Central Asian nations.' },
  { word: 'Item', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'An individual article or unit, especially one that is part of a list, collection, or set.', ex: 'The questionnaire contained forty distinct items measuring consumer satisfaction.' },
  { word: 'Job', pos: 'noun', cat: 'Work', def: 'A paid position of regular employment.', ex: 'Rapid expansion in the green technology sector has generated thousands of skilled engineering jobs.' },
  { word: 'Journal', pos: 'noun', cat: 'Education', def: 'A newspaper or magazine that deals with a particular subject or professional activity.', ex: 'Publishing peer-reviewed articles in high-impact scientific journals accelerates academic promotion.' },
  { word: 'Justify', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Show or prove to be right or reasonable.', ex: 'Candidates must justify their personal perspective with concrete examples in IELTS Task 2 essays.' },
  { word: 'Label', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A small piece of paper or fabric attached to an object giving information about it; a classifying phrase.', ex: 'Diagram completion questions require test-takers to assign the correct label to mechanical parts.' },
  { word: 'Labor', pos: 'noun', cat: 'Economics', def: 'Work, especially hard physical work; workers, especially considered as a workforce.', ex: 'Automating repetitive manufacturing operations lowers the demand for unskilled manual labor.' },
  { word: 'Layer', pos: 'noun', cat: 'Science', def: 'A sheet, quantity, or thickness of material, typically one of several, covering a surface or body.', ex: 'The stratospheric ozone layer filters hazardous ultraviolet solar rays from reaching ground level.' },
  { word: 'Lecture', pos: 'noun', cat: 'Education', def: 'An educational talk to an audience, especially to students in a university or college.', ex: 'The visiting professor delivered a captivating lecture on comparative Central Asian literature.' },
  { word: 'Legal', pos: 'adjective', cat: 'Government', def: 'Based on or concerned with the law; permitted by law.', ex: 'Enterprises must seek specialized legal counsel prior to executing cross-border corporate mergers.' },
  { word: 'Legislate', pos: 'verb', cat: 'Government', def: 'Make or enact laws.', ex: 'Parliament voted to legislate stricter emission limits for heavy commercial transport vehicles.' },
  { word: 'Levy', pos: 'verb', cat: 'Government', def: 'Impose a tax, fee, or fine.', ex: 'Municipalities levy modest tourist hospitality taxes to maintain historical monuments and parks.' },
  { word: 'Liberal', pos: 'adjective', cat: 'Society', def: 'Willing to respect or accept behavior or opinions different from one’s own; open to new ideas.', ex: 'Liberal arts colleges foster critical inquiry across literature, philosophy, and social sciences.' },
  { word: 'License', pos: 'noun', cat: 'Government', def: 'A permit from an authority to own or use something, do a particular thing, or carry on a trade.', ex: 'Commercial pilots must renew their instrument rating license through bi-annual flight simulator tests.' },
  { word: 'Likewise', pos: 'adverb', cat: 'IELTS Writing Vocabulary', def: 'In the same way; also.', ex: 'Solar energy costs have plummeted; likewise, battery storage prices have fallen precipitously.' },
  { word: 'Link', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A relationship between two things or situations, especially where one affects the other.', ex: 'Medical epidemiologists have demonstrated a direct causal link between smoking and cardiovascular illness.' },
  { word: 'Locate', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Discover the exact place or position of.', ex: 'In Reading passages, skimming topic sentences allows students to locate pertinent supporting data.' },
  { word: 'Logic', pos: 'noun', cat: 'Education', def: 'Reasoning conducted or assessed according to strict principles of validity.', ex: 'Mathematical logic underpins the architecture of modern digital algorithmic processors.' },
  { word: 'Maintain', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Cause or enable a condition or state of affairs to continue; assert strongly.', ex: 'Scholars maintain that early bilingual immersion confers lasting neuroprotective advantages.' },
  { word: 'Major', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Important, serious, or significant.', ex: 'A major advantage of electric public transport is the elimination of localized particulate exhaust.' },
  { word: 'Manipulate', pos: 'verb', cat: 'Technology', def: 'Handle or control a tool or mechanism, typically in a skillful manner; control influence unfairly.', ex: 'Surgeons manipulate robotic microscopic scalpel arms during delicate ophthalmic procedures.' },
  { word: 'Manual', pos: 'adjective', cat: 'Work', def: 'Relating to or done with the hands.', ex: 'Repetitive manual packaging tasks have been largely superseded by high-speed sorting machines.' },
  { word: 'Margin', pos: 'noun', cat: 'Business', def: 'The difference between the cost of producing something and the price needed to make a profit.', ex: 'Commercial retail franchises operate under thin operating profit margins of five to eight percent.' },
  { word: 'Mature', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Fully developed physically; having reached full natural growth or development.', ex: 'Wind turbine technology has reached a mature stage characterized by high grid reliability.' },
  { word: 'Maximize', pos: 'verb', cat: 'Economics', def: 'Make as large or great as possible; make the best use of.', ex: 'Modern agricultural enterprises deploy precision drip irrigation to maximize crop yields per liter of water.' },
  { word: 'Mechanism', pos: 'noun', cat: 'Science', def: 'A system of parts working together in a machine; a natural or established process by which something takes place.', ex: 'Scientists uncovered the cellular mechanism responsible for DNA repair following radiation exposure.' },
  { word: 'Media', pos: 'noun', cat: 'Media', def: 'The main means of mass communication (broadcasting, publishing, and the internet) regarded collectively.', ex: 'Digital news media platforms allow real-time civic participation during municipal referendums.' },
  { word: 'Mediate', pos: 'verb', cat: 'Society', def: 'Intervene between people in a dispute in order to bring about an agreement or reconciliation.', ex: 'International ombudsmen mediate commercial contract disagreements to avert costly litigation.' },
  { word: 'Medical', pos: 'adjective', cat: 'Health', def: 'Relating to the science of medicine, or to the treatment of illness and injuries.', ex: 'Advanced medical diagnostics have drastically elevated early cancer detection and survival rates.' },
  { word: 'Medium', pos: 'noun', cat: 'Media', def: 'An agency or means of doing something; a material or technical means of artistic expression.', ex: 'Podcasts have emerged as an extraordinarily popular medium for educational discourse.' },
  { word: 'Mental', pos: 'adjective', cat: 'Health', def: 'Relating to the mind; involving the process of thinking.', ex: 'Prioritizing sleep hygiene and daily physical exercise bolsters mental resilience among undergraduates.' },
  { word: 'Method', pos: 'noun', cat: 'Science', def: 'A particular form of procedure for accomplishing or approaching something, especially a systematic or established one.', ex: 'The scientific method mandates rigorous falsification testing through reproducible empirical trials.' },
  { word: 'Migrate', pos: 'verb', cat: 'Environment', def: 'Move from one region or habitat to another, according to the seasons.', ex: 'Flocks of migratory flamingos migrate to Lake Tengiz across central Kazakhstan every spring.' },
  { word: 'Military', pos: 'adjective', cat: 'Government', def: 'Relating to or characteristic of soldiers or armed forces.', ex: 'Satellite surveillance technologies originally developed for military reconnaissance now track climate patterns.' },
  { word: 'Minimal', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Of a minimum amount, quantity, or degree; negligible.', ex: 'Geothermal heating systems require minimal routine maintenance once subterranean piping is laid.' },
  { word: 'Minimize', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Reduce something, especially something unwanted, to the smallest possible amount or degree.', ex: 'Strict aerodynamic design minimizes air resistance and enhances automotive battery range.' },
  { word: 'Ministry', pos: 'noun', cat: 'Government', def: 'A government department headed by a minister.', ex: 'The Ministry of Science and Higher Education launched nationwide digital literacy grants.' },
  { word: 'Minor', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Lesser in importance, seriousness, or significance.', ex: 'The author made minor grammatical revisions to the final draft before publication.' },
  { word: 'Mode', pos: 'noun', cat: 'Technology', def: 'A way or manner in which something occurs or is experienced, expressed, or done.', ex: 'High-speed rail is rapidly becoming the preferred mode of domestic passenger transit.' },
  { word: 'Modify', pos: 'verb', cat: 'Technology', def: 'Make partial or minor changes to something, typically so as to improve it or to make it more acceptable.', ex: 'Software engineers frequently modify legacy codebase routines to enhance execution speed.' },
  { word: 'Monitor', pos: 'verb', cat: 'Science', def: 'Observe and check the progress or quality of something over a period of time.', ex: 'Sensors monitor ambient seismic oscillations around tectonic fault lines in real time.' },
  { word: 'Motive', pos: 'noun', cat: 'Psychology', def: 'A reason for doing something, especially one that is hidden or not obvious.', ex: 'Criminologists probe the psychological motives underpinning serial corporate fraud.' },
  { word: 'Mutual', pos: 'adjective', cat: 'Society', def: 'Held in common by two or more parties; experienced or done by each of two or more parties toward the other.', ex: 'International cultural exchanges foster mutual understanding and peaceful bilateral relations.' },
  { word: 'Negate', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Make ineffective; nullify; deny the existence of.', ex: 'Failing to establish paragraph coherence can negate an otherwise broad lexical vocabulary in IELTS essays.' },
  { word: 'Network', pos: 'noun', cat: 'Technology', def: 'A group or system of interconnected people or things.', ex: 'The national fiber-optic network delivers ultra-low-latency internet to remote steppe settlements.' },
  { word: 'Neutral', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Not supporting or helping either side in a conflict, disagreement, etc.; impartial.', ex: 'Academic writing demands an objective, neutral tone grounded in observable empirical facts.' },
  { word: 'Nevertheless', pos: 'adverb', cat: 'IELTS Writing Vocabulary', def: 'In spite of that; notwithstanding; all the same.', ex: 'The implementation costs were formidable; nevertheless, the long-term energy savings were indisputable.' },
  { word: 'Norm', pos: 'noun', cat: 'Society', def: 'Something that is usual, typical, or standard; a standard or pattern of social behavior that is accepted.', ex: 'Remote work arrangements have evolved from emergency measures into the prevailing corporate norm.' },
  { word: 'Notion', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A conception of or belief about something.', ex: 'Modern linguistics has discredited the erroneous notion that certain dialects are inherently superior.' },
  { word: 'Nuclear', pos: 'adjective', cat: 'Science', def: 'Relating to the nucleus of an atom, or to energy released during fission or fusion.', ex: 'Modern small modular nuclear reactors provide clean baseload electricity without carbon emissions.' },
  { word: 'Objective', pos: 'noun', cat: 'Education', def: 'A thing aimed at or sought; a goal.', ex: 'The primary educational objective of this course is to develop analytical reading competencies.' },
  { word: 'Obtain', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Get, acquire, or secure something.', ex: 'Scholars must obtain formal institutional ethics approval before surveying vulnerable populations.' },
  { word: 'Obvious', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Easily perceived or understood; clear, self-evident, or apparent.', ex: 'It is obvious that transitioning to renewable energy is indispensable for long-term climate stability.' },
  { word: 'Occupy', pos: 'verb', cat: 'Society', def: 'Reside or have one’s place of business in a building; take up a space, time, or position.', ex: 'Commercial tech enterprises occupy prime office buildings within the capital’s business district.' },
  { word: 'Occur', pos: 'verb', cat: 'Science', def: 'Happen; take place; be found or exist in a specified place or under specified conditions.', ex: 'Earthquakes of minor magnitude occur along tectonic fault zones on a daily basis.' },
  { word: 'Ongoing', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Still in progress; continuing.', ex: 'There is ongoing debate among pedagogical researchers regarding the merits of fully remote coursework.' },
  { word: 'Option', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A thing that is or may be chosen.', ex: 'Municipal leaders considered the option of subsidizing electric cargo bicycles for urban deliveries.' },
  { word: 'Orient', pos: 'verb', cat: 'Education', def: 'Align or position something relative to the points of a compass or other specified positions; adjust to a new context.', ex: 'University orientations help international freshmen orient themselves to campus facilities.' },
  { word: 'Outcome', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'The way a thing turns out; a consequence.', ex: 'A favorable educational outcome depends on regular revision, active recall, and diligent practice.' },
  { word: 'Output', pos: 'noun', cat: 'Economics', def: 'The amount of something produced by a person, machine, or industry.', ex: 'Industrial manufacturing output rebounded by eight percent following supply chain normalizations.' },
  { word: 'Overall', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Taking everything into account; regarded as a whole.', ex: 'Overall, the line graph reveals that renewable power overtook fossil fuels across the twenty-year span.' },
  { word: 'Overlap', pos: 'verb', cat: 'Science', def: 'Extend over and cover a part of; have elements in common with.', ex: 'Linguistics and cognitive psychology overlap significantly in the study of speech comprehension.' },
  { word: 'Overseas', pos: 'adjective', cat: 'Globalization', def: 'In or to a foreign country, especially one across the sea.', ex: 'Thousands of ambitious Kazakh undergraduates pursue degree coursework at overseas universities each year.' },
  { word: 'Panel', pos: 'noun', cat: 'Education', def: 'A small group of people brought together to discuss, investigate, or decide on a particular matter.', ex: 'An independent panel of medical specialists audited the clinical trial safety protocols.' },
  { word: 'Paragraph', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A distinct section of a piece of writing, usually dealing with a single theme and indicated by a new line.', ex: 'Each body paragraph in IELTS Task 2 should develop a clear central topic sentence.' },
  { word: 'Parallel', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Occurring or existing at the same time or in a similar way; corresponding.', ex: 'The researchers observed parallel trends across both urban and rural demographic survey samples.' },
  { word: 'Parameter', pos: 'noun', cat: 'Science', def: 'A numerical or other measurable factor forming one of a set that defines a system or sets the conditions of its operation.', ex: 'The software model allows hydrologists to alter rainfall parameters to simulate extreme flood events.' },
  { word: 'Participate', pos: 'verb', cat: 'Society', def: 'Be involved; take part in an activity or event.', ex: 'All enrolled students are strongly encouraged to participate in weekly English debate seminars.' },
  { word: 'Partner', pos: 'noun', cat: 'Business', def: 'A person who takes part in an undertaking with another or others, especially in a business or enterprise.', ex: 'The state enterprise established a joint venture with a leading international technology partner.' },
  { word: 'Passive', pos: 'adjective', cat: 'Psychology', def: 'Accepting or allowing what happens or what others do, without active response or resistance.', ex: 'Passive learning through uninterrupted lectures produces inferior retention compared to active discussion.' },
  { word: 'Perceive', pos: 'verb', cat: 'Psychology', def: 'Become aware or conscious of something; come to realize or understand; interpret in a particular way.', ex: 'Students perceive interactive digital simulations as more engaging than traditional textbooks.' },
  { word: 'Percent', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'One part in every hundred.', ex: 'The proportion of households with high-speed optical broadband rose to ninety-two percent.' },
  { word: 'Period', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A length or portion of time.', ex: 'Throughout the surveyed ten-year period, domestic solar power consumption increased tenfold.' },
  { word: 'Persist', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Continue firmly or obstinately in an opinion or a course of action in spite of difficulty or opposition.', ex: 'Despite aggressive policy interventions, regional income disparities persist between industrial hubs.' },
  { word: 'Perspective', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A particular attitude toward or way of regarding something; a point of view.', ex: 'From an economic perspective, investing in preventative healthcare generates immense long-term returns.' },
  { word: 'Phase', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A distinct period or stage in a series of events or a process of change or development.', ex: 'The second phase of the process involves the purification and crystallization of the chemical compound.' },
  { word: 'Phenomenon', pos: 'noun', cat: 'Science', def: 'A fact or situation that is observed to exist or happen, especially one whose cause or explanation is in question.', ex: 'Global urbanization is a complex socioeconomic phenomenon with profound environmental ramifications.' },
  { word: 'Philosophy', pos: 'noun', cat: 'Education', def: 'The study of the fundamental nature of knowledge, reality, and existence.', ex: 'Ancient Greek philosophy laid enduring foundations for Western scientific inquiry and ethical deliberation.' },
  { word: 'Physical', pos: 'adjective', cat: 'Science', def: 'Relating to the body as opposed to the mind; relating to things perceived through the senses as opposed to the mind.', ex: 'Regular physical exercise confers documented cardiovascular and psychological health benefits.' },
  { word: 'Plus', pos: 'preposition', cat: 'IELTS Academic Vocabulary', def: 'With the addition of; furthermore.', ex: 'Candidates receive sixty minutes for the reading section, plus ten minutes to transfer listening answers.' },
  { word: 'Policy', pos: 'noun', cat: 'Government', def: 'A course or principle of action adopted or proposed by a government, party, business, or individual.', ex: 'The municipal government adopted an ambitious policy aimed at electrifying all public buses.' },
  { word: 'Portion', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A part of a whole; an amount, section, or piece of something.', ex: 'A significant portion of the national budget is allocated to secondary and vocational schooling.' },
  { word: 'Pose', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Present or constitute a problem, danger, or other difficulty.', ex: 'Unregulated artificial intelligence algorithms pose formidable challenges to electoral integrity.' },
  { word: 'Positive', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Constructive, optimistic, or confident; showing presence rather than absence of a condition.', ex: 'Access to tertiary education exercises an undeniably positive influence on lifetime earning potential.' },
  { word: 'Potential', pos: 'noun', cat: 'Science', def: 'Latent qualities or abilities that may be developed and lead to future success or usefulness.', ex: 'Central Asian wind corridors possess immense potential for commercial green hydrogen synthesis.' },
  { word: 'Practitioner', pos: 'noun', cat: 'Health', def: 'A person actively engaged in an art, discipline, or profession, especially medicine.', ex: 'Experienced medical practitioners advocate lifestyle modifications prior to initiating pharmaceutical regimens.' },
  { word: 'Precede', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Come before something in time, order, or position.', ex: 'The introductory orientation will precede the commencement of the official mock examination.' },
  { word: 'Precise', pos: 'adjective', cat: 'Science', def: 'Marked by exactness and accuracy of expression or detail.', ex: 'Laboratory technicians must take precise measurements to ensure experimental reproducibility.' },
  { word: 'Predict', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Say or estimate that a specified thing will happen in the future or will be a consequence of something.', ex: 'Climatologists predict that severe droughts will become more frequent across arid zones.' },
  { word: 'Predominant', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Present as the strongest or main element.', ex: 'Natural gas remained the predominant source of electrical generation throughout the observed decade.' },
  { word: 'Preliminary', pos: 'adjective', cat: 'Science', def: 'Denoting an action or event preceding or done in preparation for something fuller or more important.', ex: 'Preliminary findings from the clinical trial indicate an eighty percent efficacy rate.' },
  { word: 'Presume', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Suppose that something is the case on the basis of probability; take for granted that something exists.', ex: 'Economists cannot presume that historic consumer patterns will remain static during inflationary spikes.' },
  { word: 'Previous', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Existing or occurring before in time or order.', ex: 'In comparison to the previous year, passenger rail traffic registered a twelve percent expansion.' },
  { word: 'Primary', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Of chief importance; principal; earliest in time or order of development.', ex: 'The primary cause of municipal air pollution during winter months is household coal heating.' },
  { word: 'Prime', pos: 'adjective', cat: 'Business', def: 'Of the best possible quality; excellent; most important of all.', ex: 'The capital’s central boulevard is a prime location for international diplomatic embassies.' },
  { word: 'Principal', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'First in order of importance; main.', ex: 'The principal argument against the proposed tax is that it disproportionately affects low-income households.' },
  { word: 'Principle', pos: 'noun', cat: 'Education', def: 'A fundamental truth or proposition that serves as the foundation for a system of belief or behavior.', ex: 'The principle of checks and balances prevents the undue concentration of executive power.' },
  { word: 'Prior', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Existing or coming before in time, order, or importance.', ex: 'Candidates must complete registration formalities prior to entering the secure test venue.' },
  { word: 'Priority', pos: 'noun', cat: 'Government', def: 'The fact or condition of being regarded or treated as more important than others.', ex: 'Modernizing regional wastewater treatment plants is an urgent public infrastructure priority.' },
  { word: 'Proceed', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Begin or continue a course of action; move forward.', ex: 'Once the listening test instructions conclude, candidates may proceed to answer question items.' },
  { word: 'Process', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A series of actions or steps taken in order to achieve a particular end.', ex: 'The flowchart illustrates the six sequential stages of the industrial cement manufacturing process.' },
  { word: 'Professional', pos: 'adjective', cat: 'Work', def: 'Relating to or belonging to a profession; competent or skillful.', ex: 'Maintaining high standards of professional integrity is non-negotiable for certified accountants.' },
  { word: 'Prohibit', pos: 'verb', cat: 'Government', def: 'Formally forbid by law, rule, or other authority.', ex: 'Environmental statutes strictly prohibit the discharge of untreated industrial effluent into rivers.' },
  { word: 'Project', pos: 'noun', cat: 'Business', def: 'An individual or collaborative enterprise that is carefully planned to achieve a particular aim.', ex: 'The trans-Eurasian transport corridor project slashed freight transit times between Asia and Europe.' },
  { word: 'Promote', pos: 'verb', cat: 'Society', def: 'Support or actively encourage a cause, venture, etc.; further the progress of.', ex: 'Community sports initiatives promote cardiovascular fitness and combat sedentary lifestyle habits.' },
  { word: 'Proportion', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A part, share, or number considered in comparative relation to a whole.', ex: 'The proportion of elderly citizens living alone climbed steadily across the surveyed period.' },
  { word: 'Prospect', pos: 'noun', cat: 'Business', def: 'The possibility or likelihood of some future event occurring.', ex: 'The prospect of entering lucrative overseas export markets spurred technological investments.' },
  { word: 'Protocol', pos: 'noun', cat: 'Science', def: 'The official procedure or system of rules governing affairs of state or diplomatic occasions; procedure for experimental execution.', ex: 'Strict laboratory sterilization protocols prevent cross-contamination during genomic sequencing.' },
  { word: 'Psychology', pos: 'noun', cat: 'Psychology', def: 'The scientific study of the human mind and its functions, especially those affecting behavior in a given context.', ex: 'Cognitive psychology investigates the mental operations involved in memory consolidation and speech retrieval.' },
  { word: 'Publish', pos: 'verb', cat: 'Media', def: 'Prepare and issue for public sale, distribution, or readership.', ex: 'Leading climatologists publish their peer-reviewed findings in international environmental periodicals.' },
  { word: 'Purchase', pos: 'verb', cat: 'Economics', def: 'Acquire something by paying for it; buy.', ex: 'Consumer willingness to purchase electric automobiles hinges upon accessible charging infrastructure.' },
  { word: 'Pursue', pos: 'verb', cat: 'Education', def: 'Follow or chase someone or something; continue or proceed along an academic or career path.', ex: 'Ambitious Kazakh scholars frequently pursue postgraduate degrees at world-renowned institutions.' },
  { word: 'Qualitative', pos: 'adjective', cat: 'Science', def: 'Relating to, measuring, or measured by the quality of something rather than its quantity.', ex: 'Ethnographic field surveys rely upon qualitative thematic interviews rather than numerical datasets.' },
  { word: 'Quantitative', pos: 'adjective', cat: 'Science', def: 'Relating to, measuring, or measured by the quantity of something rather than its quality.', ex: 'Quantitative econometric analysis revealed a robust correlation between literacy and GDP per capita.' },
  { word: 'Quote', pos: 'verb', cat: 'Education', def: 'Repeat or copy out a group of words from a text or speech written or spoken by another.', ex: 'Scholars quote primary historical eyewitness accounts to substantiate their historical theses.' },
  { word: 'Radical', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Relating to or affecting the fundamental nature of something; far-reaching or thorough.', ex: 'Mitigating climate destabilization demands radical reforms in global fossil fuel consumption.' },
  { word: 'Random', pos: 'adjective', cat: 'Science', def: 'Made, done, happening, or chosen without method or conscious decision.', ex: 'In randomized controlled trials, candidates are assigned to experimental groups at random.' },
  { word: 'Range', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'The area of variation between upper and lower limits on a particular scale; a variety of different things.', ex: 'To attain Band 8.0, candidates must demonstrate a broad range of flexible grammatical structures.' },
  { word: 'Ratio', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'The quantitative relation between two amounts showing the number of times one value contains or is contained within the other.', ex: 'The student-to-faculty ratio at the university dropped to a commendable twelve to one.' },
  { word: 'Rational', pos: 'adjective', cat: 'Psychology', def: 'Based on or in accordance with reason or logic.', ex: 'Economists classically presuppose that consumers act as rational utility-maximizing agents.' },
  { word: 'React', pos: 'verb', cat: 'Science', def: 'Respond or behave in a particular way in response to something; undergo chemical change.', ex: 'Metals react vigorously with concentrated acids to release volatile hydrogen gas.' },
  { word: 'Recover', pos: 'verb', cat: 'Economics', def: 'Return to a normal state of health, mind, or strength; regain possession or control.', ex: 'The tourism hospitality sector began to recover steadily in the aftermath of travel restrictions.' },
  { word: 'Refine', pos: 'verb', cat: 'Technology', def: 'Remove impurities or unwanted elements from a substance, typically as part of an industrial process; improve.', ex: 'Modern refineries refine domestic crude oil into high-grade aviation kerosene.' },
  { word: 'Regime', pos: 'noun', cat: 'Government', def: 'A government, especially an authoritarian one; a system or planned way of doing things.', ex: 'Strict inspection regimes ensure that commercial airliners adhere to international maintenance standards.' },
  { word: 'Region', pos: 'noun', cat: 'Environment', def: 'An area or division, especially part of a country or the world having definable characteristics.', ex: 'The arid steppes of Central Asia represent a geographically unique transcontinental region.' },
  { word: 'Register', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Enter or record on an official list or directory; express or achieve a figure.', ex: 'The manufacturing index registered a noteworthy upturn of four percent during the summer.' },
  { word: 'Regulate', pos: 'verb', cat: 'Government', def: 'Control or maintain the rate or speed of a machine or process so that it operates properly; control by rule.', ex: 'Antitrust regulators must regulate monopolistic tech conglomerates to protect fair competition.' },
  { word: 'Reinforce', pos: 'verb', cat: 'Psychology', def: 'Strengthen or support an object, substance, or argument.', ex: 'Empirical survey outcomes reinforce earlier sociological theories regarding community trust.' },
  { word: 'Reject', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Dismiss as inadequate, inappropriate, or not to one’s taste.', ex: 'The peer review panel chose to reject the submission owing to insufficient methodology controls.' },
  { word: 'Relax', pos: 'verb', cat: 'IELTS Speaking Vocabulary', def: 'Make or become less tense, anxious, or rigid; rest from work or engaging in recreation.', ex: 'Taking a stroll along the Esentai river promenade helps busy students relax after intense study.' },
  { word: 'Release', pos: 'verb', cat: 'Environment', def: 'Allow or enable to escape from confinement; set free; discharge into the atmosphere.', ex: 'Thawing permafrost reserves release potent methane emissions into the Arctic atmosphere.' },
  { word: 'Relevant', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Closely connected or appropriate to what is being done or considered.', ex: 'Every supporting point in an essay must remain strictly relevant to the question prompt.' },
  { word: 'Reluctant', pos: 'adjective', cat: 'Psychology', def: 'Unwilling and hesitant; disinclined.', ex: 'Many consumers remain reluctant to adopt fully autonomous self-driving vehicular systems.' },
  { word: 'Rely', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Depend on with full trust or confidence.', ex: 'Developing economies cannot rely indefinitely on volatile finite hydrocarbon exports.' },
  { word: 'Remove', pos: 'verb', cat: 'Technology', def: 'Take off or away from the position occupied; get rid of.', ex: 'Advanced catalytic scrubbers remove sulfur dioxide from coal power generation emissions.' },
  { word: 'Require', pos: 'verb', cat: 'Education', def: 'Need for a particular purpose; make something necessary.', ex: 'Prestigious postgraduate engineering programs require a rigorous foundation in multivariable calculus.' },
  { word: 'Research', pos: 'noun', cat: 'Science', def: 'The systematic investigation into and study of materials and sources in order to establish facts and reach new conclusions.', ex: 'Cutting-edge biomedical research promises personalized genetic therapies for rare autoimmune conditions.' },
  { word: 'Reside', pos: 'verb', cat: 'Society', def: 'Have one’s permanent home in a particular place.', ex: 'Over half of the world’s population now resides within densely populated urban agglomerations.' },
  { word: 'Resolve', pos: 'verb', cat: 'Government', def: 'Settle or find a solution to a problem, dispute, or contentious matter.', ex: 'Multilateral diplomatic dialogues helped resolve conflicting maritime fishing boundary claims.' },
  { word: 'Resource', pos: 'noun', cat: 'Environment', def: 'A stock or supply of money, materials, staff, and other assets that can be drawn on by a person or organization in order to function effectively.', ex: 'Freshwater is the most precious natural resource sustaining human agriculture in arid basins.' },
  { word: 'Respond', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Say something in reply; react quickly or favorably to something.', ex: 'Municipal emergency services respond to extreme weather incidents within six minutes on average.' },
  { word: 'Restore', pos: 'verb', cat: 'Culture', def: 'Bring back a situation or feeling that existed before; return a building, art object, etc. to its original condition.', ex: 'Conservationists worked for a decade to restore historical architectural facades along the Silk Route.' },
  { word: 'Restrain', pos: 'verb', cat: 'Government', def: 'Prevent someone or something from doing something; keep under control or within limits.', ex: 'Conservative monetary policies seek to restrain excessive inflationary credit expansions.' },
  { word: 'Restrict', pos: 'verb', cat: 'Government', def: 'Put a limit on; keep under control.', ex: 'City ordinances restrict heavy diesel freight vehicles from navigating residential streets at night.' },
  { word: 'Retain', pos: 'verb', cat: 'Education', def: 'Continue to have something; keep possession of; remember facts.', ex: 'Interactive spaced repetition quizzes help students retain sophisticated academic terminology.' },
  { word: 'Reveal', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Make previously unknown or secret information known to others; cause or allow something to be seen.', ex: 'The survey results reveal that eighty percent of commuters favor expanded rapid bus transit.' },
  { word: 'Revenue', pos: 'noun', cat: 'Economics', def: 'Income, especially when of a company or organization and of a substantial nature; a state’s annual income from taxes.', ex: 'E-commerce tax revenue funded the modernization of municipal elementary schools.' },
  { word: 'Reverse', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Move backward; turn the other way around; change to the opposite direction.', ex: 'Aggressive reforestation initiatives can reverse centuries of man-made soil desertification.' },
  { word: 'Revise', pos: 'verb', cat: 'Education', def: 'Re-examine and make alterations to written work; reread work done previously to improve one’s knowledge.', ex: 'Students must revise completed practice essays to eliminate recurring subject-verb concord flaws.' },
  { word: 'Revolution', pos: 'noun', cat: 'Technology', def: 'A dramatic and wide-reaching change in the way something works or is organized or in people’s lives.', ex: 'The digital revolution democratized access to university-level academic knowledge across the globe.' },
  { word: 'Rigid', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Unable to bend or be forced out of shape; not able to be changed or adapted.', ex: 'Overly rigid educational curricula stifle creative exploration and innovative experimentation.' },
  { word: 'Role', pos: 'noun', cat: 'Society', def: 'The function assumed or part played by a person or thing in a particular situation.', ex: 'Public libraries play a pivotal social role in integrating newly arrived immigrant families.' },
  { word: 'Route', pos: 'noun', cat: 'Travel', def: 'A way or course taken in getting from a starting point to a destination.', ex: 'The ancient Silk Route facilitated vibrant cultural and philosophical exchanges across continents.' },
  { word: 'Scenario', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A postulated sequence or development of events.', ex: 'In the worst-case climate scenario, global temperatures rise by three degrees by century’s end.' },
  { word: 'Schedule', pos: 'noun', cat: 'Work', def: 'A plan for carrying out a process or procedure, giving lists of intended events and times.', ex: 'A disciplined revision schedule enables candidates to master all four IELTS skills methodically.' },
  { word: 'Scheme', pos: 'noun', cat: 'Government', def: 'A large-scale systematic plan or arrangement for attaining some particular object or putting a particular idea into effect.', ex: 'The municipality inaugurated a shared bicycle rental scheme to reduce inner-city automobile congestion.' },
  { word: 'Scope', pos: 'noun', cat: 'Education', def: 'The extent of the area or subject matter that something deals with or to which it is relevant.', ex: 'The monograph covers a broad scope of Central Asian linguistic and cultural history.' },
  { word: 'Section', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'Any of the more or less distinct parts into which something is or may be divided or from which it is made up.', ex: 'The listening test is partitioned into four sequential sections of escalating linguistic complexity.' },
  { word: 'Sector', pos: 'noun', cat: 'Economics', def: 'An area or portion that is distinct from others; a branch of economic activity.', ex: 'The renewable energy sector generated thousands of skilled engineering jobs across the region.' },
  { word: 'Secure', pos: 'verb', cat: 'Business', def: 'Fix or fasten something so that it cannot move; succeed in obtaining something, especially with difficulty.', ex: 'The tech enterprise managed to secure substantial venture capital financing for its AI diagnostics platform.' },
  { word: 'Seek', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Attempt to find or obtain something.', ex: 'Undergraduates seek international study abroad opportunities to expand their geopolitical worldview.' },
  { word: 'Select', pos: 'verb', cat: 'Education', def: 'Carefully choose as being the best or most suitable.', ex: 'Candidates must carefully select key features rather than mechanically listing every single data point.' },
  { word: 'Sequence', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A particular order in which related events, movements, or things follow each other.', ex: 'In process diagram tasks, describing the logical sequence of stages is paramount for coherence.' },
  { word: 'Series', pos: 'noun', cat: 'Education', def: 'A number of things, events, or people of a similar kind or related nature coming one after another.', ex: 'The university hosted a prestigious series of guest lectures on atmospheric climate physics.' },
  { word: 'Shift', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A slight change in position, direction, or tendency.', ex: 'The line graph charts a noticeable shift away from print media toward digital subscriptions.' },
  { word: 'Significant', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Sufficiently great or important to be worthy of attention; noteworthy.', ex: 'There was a significant rise of thirty-five percent in electric vehicle sales between 2018 and 2022.' },
  { word: 'Similar', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Having a resemblance in appearance, character, or quantity, without being identical.', ex: 'Both European and Asian consumer markets exhibited similar trends in smartphone upgrades.' },
  { word: 'Simulate', pos: 'verb', cat: 'Technology', def: 'Imitate the appearance or character of; produce a computer model of.', ex: 'Supercomputers simulate turbulent atmospheric patterns to forecast severe hurricane paths.' },
  { word: 'Site', pos: 'noun', cat: 'Environment', def: 'An area of ground on which a town, building, or monument is constructed; a website.', ex: 'Archaeologists uncovered Neolithic stone tools at an excavation site near Lake Balkhash.' },
  { word: 'So-called', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Used to show that something or someone is commonly designated by the name specified, especially when the speaker thinks it is inappropriate.', ex: 'Critics question whether so-called fast fashion is truly economical when ecological costs are tallied.' },
  { word: 'Sole', pos: 'adjective', cat: 'Business', def: 'One and only; belonging or restricted to one person or group of people.', ex: 'The inventor remained the sole patent holder for the revolutionary water purification membrane.' },
  { word: 'Somewhat', pos: 'adverb', cat: 'IELTS Writing Vocabulary', def: 'To a moderate extent or by a moderate amount; rather.', ex: 'Consumer confidence declined somewhat during the winter but rebounded strongly by spring.' },
  { word: 'Source', pos: 'noun', cat: 'Environment', def: 'A place, person, or thing from which something comes or can be obtained.', ex: 'Geothermal reservoirs provide an exceptionally reliable source of non-intermittent clean warmth.' },
  { word: 'Specific', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Clearly defined or identified; precise and clear in statement.', ex: 'Candidates must provide specific supporting examples rather than relying upon vague generalizations.' },
  { word: 'Specify', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Identify clearly and definitely; state a fact or requirement clearly and precisely.', ex: 'The exam guidelines specify that candidates must write their answers in pencil on the answer sheet.' },
  { word: 'Sphere', pos: 'noun', cat: 'Society', def: 'An area of activity, interest, or expertise; a section of society or aspect of life.', ex: 'The internet has transformed the public sphere, enabling widespread democratic engagement.' },
  { word: 'Stable', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Not likely to change or fail; firmly established.', ex: 'Unemployment figures remained stable at approximately four percent throughout the three-year study.' },
  { word: 'Statistics', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'The practice or science of collecting and analyzing numerical data in large quantities.', ex: 'Official national statistics reveal a steady decrease in infant mortality rates over the past thirty years.' },
  { word: 'Status', pos: 'noun', cat: 'Society', def: 'The relative social, professional, or other standing of someone or something; position of affairs.', ex: 'In nomadic Kazakh society, seasoned master falconers enjoyed esteemed communal status.' },
  { word: 'Straightforward', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Uncomplicated and easy to do or understand.', ex: 'The multi-choice reading task is relatively straightforward provided students scan for synonymous phrases.' },
  { word: 'Strategy', pos: 'noun', cat: 'Education', def: 'A plan of action or policy designed to achieve a major or overall aim.', ex: 'A sound time-management strategy is essential to complete all three IELTS Reading passages in sixty minutes.' },
  { word: 'Stress', pos: 'noun', cat: 'Health', def: 'A state of mental or emotional strain or tension resulting from adverse or demanding circumstances; emphasis.', ex: 'Chronic workplace stress can precipitate cardiovascular issues and severe cognitive burnout.' },
  { word: 'Structure', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'The arrangement of and relations between the parts or elements of something complex.', ex: 'A standard IELTS Task 2 essay structure comprises an introduction, two body paragraphs, and a conclusion.' },
  { word: 'Style', pos: 'noun', cat: 'Culture', def: 'A manner of doing something; a distinctive appearance, typically determined by the principles according to which something is designed.', ex: 'Modernist architectural style in Astana features bold geometric skylines and aerodynamic glass domes.' },
  { word: 'Submit', pos: 'verb', cat: 'Education', def: 'Present a proposal, application, or piece of work to a person or body for consideration or judgment.', ex: 'Students can draft essays in the browser editor and submit them for instant diagnostic IELTS evaluation.' },
  { word: 'Subsequent', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Coming after something in time; following.', ex: 'In the subsequent decade, domestic solar adoption accelerated at an unprecedented pace.' },
  { word: 'Subsidiary', pos: 'adjective', cat: 'Business', def: 'Less important than but related or supplementary to something; a company controlled by a holding company.', ex: 'The multinational telecommunications enterprise established a regional subsidiary in Almaty.' },
  { word: 'Substitute', pos: 'noun', cat: 'Environment', def: 'A person or thing acting or serving in place of another.', ex: 'Biodegradable seaweed packaging is an eco-friendly substitute for single-use petrochemical plastics.' },
  { word: 'Successive', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Following one another or others without interruption; consecutive.', ex: 'For five successive years, the municipality recorded double-digit declines in vehicular carbon emissions.' },
  { word: 'Sufficient', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Enough; adequate.', ex: 'Candidates must ensure they have sufficient time remaining to proofread their completed writing responses.' },
  { word: 'Sum', pos: 'noun', cat: 'Economics', def: 'A particular amount of money; the total amount resulting from the addition of two or more numbers.', ex: 'The ministry allocated a substantial sum toward subsidizing electric public transit buses.' },
  { word: 'Summary', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A brief statement or account of the main points of something.', ex: 'The overview paragraph in Task 1 functions as an executive summary of key chart features.' },
  { word: 'Supplement', pos: 'verb', cat: 'Health', def: 'Add an extra element or amount to something.', ex: 'Athletes frequently supplement their balanced diets with micronutrients and whey proteins.' },
  { word: 'Survey', pos: 'noun', cat: 'Science', def: 'A general view, examination, or description of someone or something; an investigation of opinions or behavior.', ex: 'A nationwide survey revealed that seventy-five percent of citizens endorse renewable energy investments.' },
  { word: 'Survive', pos: 'verb', cat: 'Environment', def: 'Continue to live or exist, especially in spite of danger or hardship.', ex: 'Desert flora survive extreme aridity by storing moisture within specialized waxy leaf structures.' },
  { word: 'Suspend', pos: 'verb', cat: 'Government', def: 'Temporarily prevent from continuing or being in force or effect.', ex: 'Aviation authorities were forced to suspend international flights during the volcanic ash cloud crisis.' },
  { word: 'Sustain', pos: 'verb', cat: 'Environment', def: 'Strengthen or support physically or mentally; maintain over a prolonged period.', ex: 'Ecosystems require clean freshwater runoff to sustain rich biological diversity.' },
  { word: 'Symbol', pos: 'noun', cat: 'Culture', def: 'A thing that represents or stands for something else, especially a material object representing something abstract.', ex: 'The soaring golden eagle on the national flag of Kazakhstan is an enduring symbol of liberty and dignity.' },
  { word: 'Tape', pos: 'noun', cat: 'Technology', def: 'A narrow strip of material, typically used to hold or fasten something; magnetic recording medium.', ex: 'Historians digitized thousands of vintage magnetic audio tapes containing folk oral epics.' },
  { word: 'Target', pos: 'noun', cat: 'Education', def: 'A person, object, or place selected as the aim of attack; an objective or result towards which efforts are directed.', ex: 'Setting a clear target band score keeps students focused and motivated throughout preparation.' },
  { word: 'Task', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A piece of work to be done or undertaken.', ex: 'IELTS Writing Task 1 demands an objective factual report of at least one hundred and fifty words.' },
  { word: 'Team', pos: 'noun', cat: 'Work', def: 'A group of people working together on a coordinated task.', ex: 'A multidisciplinary team of geneticists and bioinformaticians cracked the wheat drought resistance genome.' },
  { word: 'Technical', pos: 'adjective', cat: 'Technology', def: 'Relating to a particular subject, art, or craft, or its practical skills.', ex: 'Reading passage 3 often contains dense technical vocabulary relating to cognitive science or geology.' },
  { word: 'Technique', pos: 'noun', cat: 'Education', def: 'A way of carrying out a particular task, especially the execution or performance of an artistic work or a scientific procedure.', ex: 'Skimming and scanning are foundational reading techniques that save precious examination time.' },
  { word: 'Technology', pos: 'noun', cat: 'Technology', def: 'The application of scientific knowledge for practical purposes, especially in industry.', ex: 'Advancements in renewable battery technology have catalyzed the transition away from fossil hydrocarbons.' },
  { word: 'Temporary', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Lasting for only a limited period of time; not permanent.', ex: 'Emergency tent shelters provided temporary refuge for villagers evacuated during spring river floods.' },
  { word: 'Tense', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Stretched tight, rigid; nervous; a set of forms taken by a verb to indicate the time of the action.', ex: 'Accurate usage of past and present perfect tenses is crucial for describing Task 1 historical trends.' },
  { word: 'Terminate', pos: 'verb', cat: 'Business', def: 'Bring to an end; end the employment of someone.', ex: 'The municipal transit authority voted to terminate the contract with the unreliable bus vendor.' },
  { word: 'Text', pos: 'noun', cat: 'Education', def: 'A book or other written or printed work, regarded in terms of its content rather than its physical form.', ex: 'Authentic IELTS Academic reading texts are drawn from reputable books, journals, magazines, and newspapers.' },
  { word: 'Theme', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'The subject of a talk, piece of writing, exhibition, etc.; a topic.', ex: 'Environmental conservation and green urbanization are recurring themes in IELTS essay prompts.' },
  { word: 'Theory', pos: 'noun', cat: 'Science', def: 'A supposition or a system of ideas intended to explain something, especially one based on general principles independent of the thing to be explained.', ex: 'Einstein’s general theory of relativity transformed human comprehension of gravity and spacetime curvature.' },
  { word: 'Thereby', pos: 'adverb', cat: 'IELTS Writing Vocabulary', def: 'By that means; as a result of that.', ex: 'The government subsidized electric vehicles, thereby reducing urban greenhouse emissions significantly.' },
  { word: 'Thesis', pos: 'noun', cat: 'Education', def: 'A long essay or dissertation involving personal research, written by a candidate for a university degree; a central proposition.', ex: 'A lucid thesis statement in the introductory paragraph anchors the entire argument in Task 2.' },
  { word: 'Topic', pos: 'noun', cat: 'IELTS Academic Vocabulary', def: 'A matter dealt with in a text, discourse, or conversation; a subject.', ex: 'Speaking Part 2 prompts present candidates with a cue card covering an everyday personal topic.' },
  { word: 'Trace', pos: 'verb', cat: 'Science', def: 'Find or discover by investigation; follow the course or development of something.', ex: 'Archaeologists can trace ancient nomadic migration pathways through satellite radar imaging.' },
  { word: 'Tradition', pos: 'noun', cat: 'Culture', def: 'The transmission of customs or beliefs from generation to generation.', ex: 'Kazakh horse-riding traditions such as Kokpar celebrate agility, courage, and communal solidarity.' },
  { word: 'Transfer', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Move from one place to another.', ex: 'In the paper-based listening test, candidates receive ten minutes to transfer answers to the official sheet.' },
  { word: 'Transform', pos: 'verb', cat: 'Technology', def: 'Make a thorough or dramatic change in the form, appearance, or character of.', ex: 'Ubiquitous mobile smartphones transform the way citizens interact with banking and municipal services.' },
  { word: 'Transit', pos: 'noun', cat: 'Travel', def: 'The carrying of people or things from one place to another.', ex: 'Expanding rapid bus transit corridors reduced commute times by thirty percent across the metropolitan area.' },
  { word: 'Transmit', pos: 'verb', cat: 'Technology', def: 'Cause something to pass on from one place or person to another; broadcast.', ex: 'Fiber-optic telecommunications cables transmit terabytes of encrypted scientific data across continents.' },
  { word: 'Transport', pos: 'noun', cat: 'Travel', def: 'A system or means of conveying people or goods from place to place.', ex: 'Public electric transport networks are indispensable for creating sustainable zero-emission cities.' },
  { word: 'Trend', pos: 'noun', cat: 'IELTS Writing Vocabulary', def: 'A general direction in which something is developing or changing.', ex: 'The line graph illustrates an upward trend in global renewable energy generation between 2000 and 2020.' },
  { word: 'Trigger', pos: 'verb', cat: 'Psychology', def: 'Cause an event or situation to happen or exist; precipitate a psychological reaction.', ex: 'Sensory environmental cues can trigger vivid nostalgic memories stored deep within the subconscious mind.' },
  { word: 'Ultimate', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Being or happening at the end of a process; final; basic or fundamental.', ex: 'The ultimate objective of linguistic study is to foster authentic, empathetic intercultural dialogue.' },
  { word: 'Undergo', pos: 'verb', cat: 'Science', def: 'Experience or be subjected to something, typically something unpleasant, arduous, or requiring change.', ex: 'Industrial recycling materials undergo intensive mechanical sorting and high-temperature thermal sterilization.' },
  { word: 'Underlie', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Be the fundamental cause or basis of something.', ex: 'Profound socio-economic inequalities underlie many contemporary urban migration challenges.' },
  { word: 'Undertake', pos: 'verb', cat: 'IELTS Academic Vocabulary', def: 'Commit oneself to and begin an enterprise or responsibility; take on.', ex: 'Researchers decided to undertake a five-year longitudinal study tracking bilingual childhood development.' },
  { word: 'Uniform', pos: 'adjective', cat: 'Science', def: 'Remaining the same in all cases and at all times; unchanging in form or character.', ex: 'The laboratory incubator maintains a uniform ambient temperature of thirty-seven degrees Celsius.' },
  { word: 'Unify', pos: 'verb', cat: 'Society', def: 'Make or become united, uniform, or whole.', ex: 'Communal cultural celebrations unify diverse ethnic traditions under a shared national civic identity.' },
  { word: 'Unique', pos: 'adjective', cat: 'Culture', def: 'Being the only one of its kind; unlike anything else.', ex: 'The architectural design of the Baiterek tower in Astana draws inspiration from a unique ancient steppe myth.' },
  { word: 'Utilize', pos: 'verb', cat: 'Technology', def: 'Make practical and effective use of.', ex: 'Modern agricultural enterprises utilize sensor-equipped drones to monitor crop moisture levels.' },
  { word: 'Valid', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Having a sound basis in logic or fact; of having legal force.', ex: 'A valid IELTS test report form is recognized by over twelve thousand institutions globally for two full years.' },
  { word: 'Vary', pos: 'verb', cat: 'IELTS Writing Vocabulary', def: 'Differ in size, amount, degree, or nature from something else of the same general class.', ex: 'Tuition fees vary significantly depending upon the tier and geographic location of the university.' },
  { word: 'Vehicle', pos: 'noun', cat: 'Travel', def: 'A thing used for transporting people or goods, especially on land, such as a car, truck, or cart; a medium.', ex: 'Electric vehicles represent a crucial technology for decarbonizing metropolitan commuting networks.' },
  { word: 'Version', pos: 'noun', cat: 'Technology', def: 'A particular form of something differing in certain respects from earlier forms or from other embodiments.', ex: 'Candidates can select between the Academic and General Training versions of the IELTS examination.' },
  { word: 'Via', pos: 'preposition', cat: 'Travel', def: 'Traveling through a place on the way to a destination; by means of a specified person or thing.', ex: 'The flight from Almaty to London connects via modern hubs in Frankfurt or Istanbul.' },
  { word: 'Violate', pos: 'verb', cat: 'Government', def: 'Break or fail to comply with a rule or formal agreement.', ex: 'Enterprises that violate environmental emissions regulations face severe financial sanctions.' },
  { word: 'Virtual', pos: 'adjective', cat: 'Technology', def: 'Not physically existing as such but made by software to appear to do so.', ex: 'Virtual laboratory environments allow chemistry undergraduates to rehearse hazardous procedures safely.' },
  { word: 'Visible', pos: 'adjective', cat: 'IELTS Writing Vocabulary', def: 'Able to be seen; perceptible to the eye; apparent.', ex: 'A visible decline in coal dependency was evident across all European industrialized nations by 2020.' },
  { word: 'Vision', pos: 'noun', cat: 'Society', def: 'The faculty or state of being able to see; the ability to think about or plan the future with imagination or wisdom.', ex: 'The strategic vision of IELTS MASTER is to democratize high-caliber exam preparation for all learners.' },
  { word: 'Visual', pos: 'adjective', cat: 'Education', def: 'Relating to seeing or sight.', ex: 'Visual charts, including graphs and diagrams, provide an intuitive representation of complex numeric datasets.' },
  { word: 'Volume', pos: 'noun', cat: 'Economics', def: 'The amount of space that a substance or object occupies; an amount or quantity of something, especially when great.', ex: 'International maritime trade volume expanded by five percent following port modernizations.' },
  { word: 'Voluntary', pos: 'adjective', cat: 'Society', def: 'Done, given, or acting of one’s own free will.', ex: 'Thousands of young citizens participate in voluntary tree-planting campaigns across the country each spring.' },
  { word: 'Welfare', pos: 'noun', cat: 'Society', def: 'The health, happiness, and fortunes of a person or group; financial support given to people in need.', ex: 'A robust public welfare framework safeguards vulnerable households from sudden economic shocks.' },
  { word: 'Whereas', pos: 'conjunction', cat: 'IELTS Writing Vocabulary', def: 'In contrast or comparison with the fact that.', ex: 'Coal power generation plunged by fifty percent, whereas solar and wind generation expanded fivefold.' },
  { word: 'Whereby', pos: 'adverb', cat: 'IELTS Academic Vocabulary', def: 'By which; according to which.', ex: 'The ministry instituted a meritocratic framework whereby top scholars receive full tuition waivers.' },
  { word: 'Widespread', pos: 'adjective', cat: 'IELTS Academic Vocabulary', def: 'Found or distributed over a large area or number of people.', ex: 'There is widespread public consensus regarding the necessity of reducing single-use plastic waste.' },
  { word: 'Yield', pos: 'verb', cat: 'Economics', def: 'Produce or provide a natural, agricultural, or industrial product; give way.', ex: 'Modern organic farming practices yield nutrient-dense produce while preserving soil microbiological health.' }
];

// Add the academic words
academicWordsList.forEach((w, index) => {
  vocabularyDatabase.push({
    id: `v-acad-${index + 1}`,
    word: w.word,
    phonetic: `/${w.word.toLowerCase()}/`,
    partOfSpeech: w.pos,
    category: w.cat,
    cefrLevel: 'C1',
    targetBand: '7.5+',
    definition: w.def,
    exampleSentence: w.ex,
    synonyms: ['Synonym', 'Academic equivalent'],
    collocations: [`Key ${w.word.toLowerCase()}`, `Essential ${w.word.toLowerCase()}`]
  });
});
